// src/content/consent.ts
// CW31 (BTIE D10), the content service's half of consent. Two switches the
// session has always stored and nothing honoured: `trackingConsent` and
// `personalizationEnabled`. Either off means the shopper gets the site's own
// defaults, the holdout's `default` arm, whatever the hash would have said.
// Tracking off also means the engine writes nothing about the request: no
// decision record, no ring, no exposure, no outcome. Absent means consenting,
// which is what every stored session and every object already says today.
//
// The session host carries the switches on `preferences`; the shopper object
// reports them as `consent: { tracking, personalization }` on its snapshot and
// on its ingest envelope (the delivery session's half); the SDK's cookies
// mirror them for the paths that only see the request.

import type { Arm } from './types';

export interface Consent { tracking: boolean; personalization: boolean }
export const CONSENTING: Consent = { tracking: true, personalization: true };

const flag = (v: unknown, fallback: boolean): boolean => (typeof v === 'boolean' ? v : v === 'true' ? true : v === 'false' ? false : fallback);

/** From a session's preferences or an object's `consent` block; anything missing reads as consenting. */
export function consentOf(src: {
  preferences?: { trackingConsent?: unknown; personalizationEnabled?: unknown } | null;
  consent?: { tracking?: unknown; personalization?: unknown } | null;
} | null | undefined): Consent {
  const tracking = flag(src?.consent?.tracking, flag(src?.preferences?.trackingConsent, true));
  const personalization = flag(src?.consent?.personalization, flag(src?.preferences?.personalizationEnabled, true));
  return { tracking, personalization };
}

/** From the request's cookies, which the session host mirrors the preferences into. */
export function consentFromCookies(cookieHeader: string | null | undefined): Consent {
  const jar: Record<string, string> = {};
  for (const part of (cookieHeader ?? '').split(';')) {
    const at = part.indexOf('=');
    if (at > 0) jar[part.slice(0, at).trim()] = part.slice(at + 1).trim();
  }
  return { tracking: flag(jar.opt_tracking_consent, true), personalization: flag(jar.opt_personalization_enabled, true) };
}

/** Whether the engine may personalize for this shopper at all. */
export const personalizes = (c: Consent): boolean => c.tracking && c.personalization;

/** The arm the shopper actually gets: the site's defaults unless both switches are on. */
export const armUnder = (c: Consent, arm: Arm): Arm => (personalizes(c) ? arm : 'default');

// src/identity/link.ts
// ---------------------------------------------------------------------------
// The link itself: a browser becomes a person's, and the profile follows.
//
// Whichever host holds the profile (the KV session today, the shopper object
// when REFLEX_HOST is 'do'), the steps are the same and in the same order:
//
//   1. name the person: shopperIdFor(tenant, accountId)
//   2. record the link, and learn whether this browser is new to the person,
//      already theirs, or moving from someone else
//   3. new: fold the browser's profile into the person's, and leave the
//      browser's record forwarding there
//      moving: only repoint; what it learned went to the first person
//      already: nothing
//   4. tell the client the id to carry from now on
//
// Step 3 is where the two hosts differ, and only there.
//
// WHAT A LINK IS NOT. It is not a login. The site knows who is signed in; this
// records that the site said so, with how much assurance, and merges profiles
// accordingly. And it is not reversible by design: a merged profile is one
// profile. "Log out" is a client act, detach (identity/detach) plus a fresh
// anonymous id, and the person's profile stays whole for their next sign-in.
// ---------------------------------------------------------------------------

import type { Env } from '@/types/env';
import type { TenantId } from '@/tenancy/tenant';
import { shopperObject, shopperObjectName } from '@/tenancy/objects';
import { resolveReflexConfig, resolveSurface } from '@/demos/registry';
import { SessionManager, type SessionData } from '@/services/SessionManager';
import type { ReflexChanges } from '@/reflex/core';
import { IdentityStore, type LinkSource } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import type { Assurance } from '@/identity/assertion';
import { assertSessionTarget, SessionAccessError, SHOPPER_HEADER, type SessionCapability } from '@/identity/sessionCapability';

export type LinkOutcome = 'linked' | 'already' | 'relinked';

export interface LinkResult {
  shopperId: string;
  visitorId: string;
  outcome: LinkOutcome;
  assurance: Assurance;
  /** Session host only: the person's session id, for the cookie. */
  sessionId: string | null;
  /** What the merge did to the person's memberships. Empty when nothing merged. */
  changes: ReflexChanges;
  audiences: string[];
  cookieHeaders: string[];
}

/** A visitor id we will link: the client's own format, bounded, never a namespace. */
export function validVisitorId(id: unknown): id is string {
  return typeof id === 'string' && /^[A-Za-z0-9_.\-]{1,200}$/.test(id);
}

export async function linkVisitor(
  env: Env,
  tenant: TenantId,
  input: {
    visitorId: string; accountId: string; source: LinkSource; assurance: Assurance; now?: number;
    /** The session id on the request's cookie, if any: where the browser's own record lives once its `user:` key points at a person. */
    cookieSessionId?: string | null;
    /** Public link ingress only; trusted history/import callers omit this. */
    principal?: SessionCapability;
    capability?: string;
  },
): Promise<LinkResult> {
  const now = input.now ?? Date.now();
  let ownedSource: { id: string; data: SessionData } | null | undefined;
  if (input.principal) {
    assertSessionTarget(input.principal, input.visitorId);
    if (input.principal.kind !== 'anonymous' || input.principal.tenant !== tenant) throw new SessionAccessError();
    if ((env.REFLEX_HOST ?? 'session') !== 'do') {
      const data = await new SessionManager(env, { tenant, principal: input.principal }).getSession(input.principal.sessionId);
      ownedSource = data ? { id: input.principal.sessionId, data } : null;
    } else {
      const res = await shopperObject(env.SHOPPER_REFLEX, input.visitorId, tenant).fetch('https://shopper-reflex/identity/export', {
        headers: { [SHOPPER_HEADER]: input.capability ?? '', 'X-Tenant': tenant },
      });
      if (!res.ok) throw new SessionAccessError();
      const source = await res.json() as { forwardTo?: unknown; affinity?: { shopperId?: unknown } };
      if (source.forwardTo || (source.affinity && source.affinity.shopperId !== input.visitorId)) throw new SessionAccessError();
    }
  }
  const shopperId = await shopperIdFor(env, tenant, input.accountId);
  if (input.principal) assertSessionTarget(input.principal, input.visitorId);
  const store = new IdentityStore(env.SESSIONS as never, tenant);

  const { outcome } = await store.link({
    visitorId: input.visitorId, shopperId, assurance: input.assurance, source: input.source,
    salted: isSalted(env), now,
  });

  const base: Omit<LinkResult, 'sessionId' | 'changes' | 'audiences' | 'cookieHeaders'> = {
    shopperId, visitorId: input.visitorId, outcome, assurance: input.assurance,
  };

  if ((env.REFLEX_HOST ?? 'session') === 'do') {
    const r = await linkOnObjectHost(env, tenant, input.visitorId, shopperId, outcome, now);
    return { ...base, cookieHeaders: [], ...r };
  }
  const r = await linkOnSessionHost(env, tenant, input.visitorId, shopperId, outcome, now, input.cookieSessionId ?? null, ownedSource);
  // CW28: the browser's own record now forwards to the person and nothing else
  // points at it; the link remembers it so an erasure can reach it.
  if (r.ownSessionId) await store.noteOwnSession(input.visitorId, r.ownSessionId);
  return { ...base, sessionId: r.sessionId, changes: r.changes, audiences: r.audiences, cookieHeaders: r.cookieHeaders };
}

// ── The session host ─────────────────────────────────────────────────────────

async function linkOnSessionHost(
  env: Env, tenant: TenantId, visitorId: string, shopperId: string, outcome: LinkOutcome, now: number,
  cookieSessionId: string | null,
  ownedSource?: { id: string; data: SessionData } | null,
): Promise<Pick<LinkResult, 'sessionId' | 'changes' | 'audiences' | 'cookieHeaders'> & { ownSessionId: string | null }> {
  const sm = new SessionManager(env, { tenant });
  const none: ReflexChanges = { entered: [], exited: [], explain: [] };

  // The browser's OWN record: the one named by this visitor id, carrying no
  // identity. After a first link the `user:` key points at the person, so the
  // cookie is tried first; a record that turns out to be a person's is not the
  // browser's and is left alone.
  const own = async (sid: string | null): Promise<{ id: string; data: SessionData } | null> => {
    if (!sid) return null;
    const data = await sm.readRaw(sid);
    return data && !data.identity && data.userId === visitorId ? { id: sid, data } : null;
  };
  const browser = ownedSource !== undefined ? ownedSource : (await own(cookieSessionId)) ?? (await own(await sm.resolveSessionIdByUserId(visitorId)));
  const fromSessionId = browser?.id ?? null;
  const fromRaw = browser?.data ?? null;
  const cfg = await resolveReflexConfig(env, resolveSurface({ surface: fromRaw?.surface }));

  if (outcome === 'already') {
    // Nothing to merge; still answer with the person's session so the cookie can follow.
    const sid = await sm.resolveSessionIdByUserId(shopperId);
    const data = sid ? await sm.readRaw(sid) : null;
    if (sid && data) {
      return { sessionId: sid, changes: none, audiences: data.reflex?.audiences ?? [], cookieHeaders: sm.createCookieHeaders(sm.generateSessionCookies(data, sid)), ownSessionId: fromSessionId };
    }
    // The link exists but the person's session expired: make one from what the browser has.
  }

  const absorbed = await sm.absorbIntoShopper({
    shopperId, visitorId, from: fromRaw, fromSessionId, config: cfg, now,
    mode: outcome === 'relinked' ? 'repoint' : 'merge',
  });
  return {
    sessionId: absorbed.sessionId,
    changes: absorbed.changes,
    audiences: absorbed.data.reflex?.audiences ?? [],
    cookieHeaders: sm.createCookieHeaders(sm.generateSessionCookies(absorbed.data, absorbed.sessionId)),
    ownSessionId: fromSessionId && fromSessionId !== absorbed.sessionId ? fromSessionId : null,
  };
}

// ── The object host ──────────────────────────────────────────────────────────

async function linkOnObjectHost(
  env: Env, tenant: TenantId, visitorId: string, shopperId: string, outcome: LinkOutcome, now: number,
): Promise<Pick<LinkResult, 'changes' | 'audiences' | 'sessionId'>> {
  const none: ReflexChanges = { entered: [], exited: [], explain: [] };
  const person = shopperObject(env.SHOPPER_REFLEX, shopperId, tenant);
  const browser = shopperObject(env.SHOPPER_REFLEX, visitorId, tenant);
  const personName = shopperObjectName(tenant, shopperId);

  if (outcome === 'already') {
    const snap = (await (await person.fetch('https://shopper-reflex/snapshot')).json()) as { sessionId?: string; affinity?: { audiences?: string[] } | null };
    return { changes: none, audiences: snap.affinity?.audiences ?? [], sessionId: snap.sessionId ?? null };
  }

  let audiences: string[] = [];
  let changes = none;
  let sessionId: string | null = null;
  if (outcome === 'linked') {
    const exported = (await (await browser.fetch('https://shopper-reflex/identity/export')).json()) as {
      affinity?: unknown; pipeline?: unknown; forwardTo?: string | null;
    };
    // A browser already forwarding elsewhere has nothing of its own to fold in.
    const payload = exported.forwardTo ? { shopperId, now } : { shopperId, now, affinity: exported.affinity ?? null, pipeline: exported.pipeline ?? null };
    const absorbed = (await (await person.fetch('https://shopper-reflex/identity/absorb', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
    })).json()) as { audiences?: string[]; changes?: ReflexChanges; sessionId?: string };
    sessionId = absorbed.sessionId ?? null;
    audiences = absorbed.audiences ?? [];
    changes = absorbed.changes ?? none;
  } else {
    // relinked: make sure the person's object exists and carries the id, fold nothing.
    const absorbed = await (await person.fetch('https://shopper-reflex/identity/absorb', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ shopperId, now }),
    })).json() as { sessionId?: string };
    sessionId = absorbed.sessionId ?? null;
  }
  await browser.fetch('https://shopper-reflex/identity/forward', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ to: personName }),
  });
  return { changes, audiences, sessionId };
}

// src/routes/identity.ts
// ---------------------------------------------------------------------------
// CW25 — identity stitching (scope appendix §1.12, ledger 20 row 2).
//
//   POST /v1/:tenant/identity/link      the site says who this browser is
//   POST /v1/:tenant/identity/detach    this browser stops being anyone (logout)
//   POST /v1/:tenant/identity/resolve   account id → shopper id, for the warehouse
//   GET  /v1/:tenant/identity/visitor/:visitorId   which person, if any
//   GET  /v1/:tenant/identity/shopper/:shopperId   which browsers, and the history applied
//   POST /v1/:tenant/identity/events    historical rows, JSON or CSV
//   POST /v1/:tenant/identity/erase     the right to be forgotten: links, profiles, ledger rows
//
// Mounted under /v1, so the site-key gate (CW10) covers everything here. The
// link and detach are the SDK's calls. Linking always also requires a backend
// signed assertion; missing verification configuration refuses it. The rest is the
// data team's and wants the operator token, like the ledger routes.
// ---------------------------------------------------------------------------

import { Hono } from 'hono';
import { z } from 'zod';
import type { Env } from '@/types/env';
import type { TenantVariables } from '@/tenancy/tenant';
import { jwt } from '@/middleware/auth';
import { SessionManager } from '@/services/SessionManager';
import { verifyAssertion } from '@/identity/assertion';
import { linkVisitor, validVisitorId } from '@/identity/link';
import { IdentityStore } from '@/identity/store';
import { isSalted, isShopperId, shopperIdFor } from '@/identity/shopperId';
import { applyHistory, historyRowSchema, parseHistoryCsv, MAX_ROWS } from '@/identity/history';
import { eraseSubject } from '@/identity/erase';
import type { AuthContext } from '@/middleware/auth';
import { requireShopper, shopperPrincipal, capabilityToken, verifySessionCapability, newAnonymousSession, issueSessionCapability, assertSessionTarget, SessionAccessError } from '@/identity/sessionCapability';
import { tenantForRequest } from '@/tenancy/middleware';

export const identityRoutes = new Hono<{ Bindings: Env; Variables: TenantVariables }>();

const TENANT = /^[a-z0-9][a-z0-9_-]{0,63}$/i;

const linkSchema = z.object({
  visitorId: z.string().trim().min(1).max(200),
  accountId: z.string().trim().min(1).max(200),
  source: z.enum(['login', 'signup', 'checkout', 'import', 'other']).default('login'),
  exp: z.number().int().optional(),
  assertion: z.string().min(1).max(200).optional(),
});

function tenantOf(c: { req: { param(name: string): string | undefined } }): string | null {
  const t = (c.req.param('tenant') ?? '').trim();
  return TENANT.test(t) ? t : null;
}

/**
 * The link. Returns the id the client carries from now on. On the session host
 * the response also sets the session cookie to the person's session, so every
 * tab on this device lands there on its next request without any forwarding.
 */
identityRoutes.post('/:tenant/identity/session', async (c) => {
  const tenant = tenantOf(c);
  if (!tenant || tenant !== (c.get('tenant') ?? tenantForRequest(c.env, c.req.raw))) throw new SessionAccessError();
  const token = capabilityToken(c.req.raw);
  const session = token === null ? await newAnonymousSession(c.env, tenant)
    : { ...await verifySessionCapability(c.env, token, tenant), capability: token };
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, session });
});

identityRoutes.post('/:tenant/identity/link', requireShopper(), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: unknown;
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const parsed = linkSchema.safeParse(body);
  if (!parsed.success) return c.json({ ok: false, error: parsed.error.issues[0]?.message ?? 'invalid body' }, 400);
  const { visitorId, accountId, source, exp, assertion } = parsed.data;
  const principal = shopperPrincipal(c.req.raw);
  assertSessionTarget(principal, visitorId);

  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (isShopperId(visitorId)) {
    // A browser already carrying a person's id is signed in as that person.
    // Linking it to another account would fold one person into another.
    return c.json({ ok: false, error: 'this browser already carries a shopper id; detach first' }, 409);
  }

  const verdict = await verifyAssertion(c.env, tenant, { visitorId, accountId, exp, assertion });
  if (!verdict.ok) return c.json({ ok: false, error: verdict.reason }, 401);

  const result = await linkVisitor(c.env, tenant, { visitorId, accountId, source, assurance: verdict.assurance, principal, capability: capabilityToken(c.req.raw)! });
  if (!result.sessionId) throw new SessionAccessError();
  const session = await issueSessionCapability(c.env, { tenant, subject: result.shopperId, sessionId: result.sessionId, kind: 'recognized' });
  for (const h of result.cookieHeaders) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({
    ok: true,
    tenant,
    shopperId: result.shopperId,
    visitorId: result.visitorId,
    outcome: result.outcome,
    assurance: result.assurance,
    salted: isSalted(c.env),
    audiences: result.audiences,
    changes: { entered: result.changes.entered, exited: result.changes.exited },
    // What the client does next, spelled out so no SDK has to guess.
    carry: result.shopperId,
    session,
  });
});

/**
 * Detach: clear this device's session cookies and nothing else. The person's
 * profile stays whole for their next sign-in; the client mints a fresh
 * anonymous id. Erasure is a different door (session reset), on purpose.
 */
identityRoutes.post('/:tenant/identity/detach', requireShopper(), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const sm = new SessionManager(c.env, { tenant });
  for (const h of sm.clearCookieHeaders()) c.header('Set-Cookie', h, { append: true });
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, tenant, detached: true, session: await newAnonymousSession(c.env, tenant) });
});

/** The warehouse's join key for an account, without the warehouse holding the salt. */
identityRoutes.post('/:tenant/identity/resolve', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { accountIds?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const ids = Array.isArray(body.accountIds) ? body.accountIds.filter((x): x is string => typeof x === 'string' && x.trim() !== '').slice(0, 1000) : [];
  if (ids.length === 0) return c.json({ ok: false, error: 'accountIds: string[] required' }, 400);
  const resolved: Record<string, string> = {};
  for (const id of ids) resolved[id] = await shopperIdFor(c.env, tenant, id);
  return c.json({ ok: true, tenant, salted: isSalted(c.env), resolved });
});

identityRoutes.get('/:tenant/identity/visitor/:visitorId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const visitorId = (c.req.param('visitorId') ?? '').trim();
  if (!validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const link = await store.visitorLink(visitorId);
  return c.json({ ok: true, tenant, visitorId, shopperId: isShopperId(visitorId) ? visitorId : (link?.shopperId ?? null), link });
});

identityRoutes.get('/:tenant/identity/shopper/:shopperId', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const shopperId = (c.req.param('shopperId') ?? '').trim();
  if (!isShopperId(shopperId)) return c.json({ ok: false, error: 'not a shopper id' }, 400);
  const store = new IdentityStore(c.env.SESSIONS as never, tenant);
  const rec = await store.shopper(shopperId);
  if (!rec) return c.json({ ok: false, error: 'unknown shopper' }, 404);
  return c.json({ ok: true, tenant, shopper: rec });
});

/**
 * Historical rows. `application/json` with `{ rows: [...] }`, or `text/csv`
 * with a header row. Each row is validated; a bad row fails the request, a row
 * that names nobody or carries no registry attribute is skipped and reported.
 */
identityRoutes.post('/:tenant/identity/events', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  const ct = (c.req.header('Content-Type') ?? '').toLowerCase();
  let raw: unknown[];
  if (ct.includes('text/csv')) {
    raw = parseHistoryCsv(await c.req.text());
  } else {
    let body: { rows?: unknown } = {};
    try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
    raw = Array.isArray(body.rows) ? body.rows : [];
  }
  if (raw.length === 0) return c.json({ ok: false, error: 'no rows' }, 400);
  if (raw.length > MAX_ROWS) return c.json({ ok: false, error: `at most ${MAX_ROWS} rows per request` }, 413);
  const parsed = z.array(historyRowSchema).safeParse(raw);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    return c.json({ ok: false, error: `row ${String(issue?.path[0] ?? '?')}: ${issue?.message ?? 'invalid'}` }, 400);
  }
  const report = await applyHistory(c.env, tenant, parsed.data);
  return c.json({ ok: true, tenant, ...report });
});

/**
 * CW28. Forget a person, or an unlinked browser: the link table, every
 * profile, and the ledger rows (tombstoned at once, rewritten nightly by the
 * ledger's job). Operator token. The receipt lists what was erased and what
 * this cannot reach.
 */
identityRoutes.post('/:tenant/identity/erase', jwt({ required: true }), async (c) => {
  const tenant = tenantOf(c);
  if (!tenant) return c.json({ ok: false, error: 'tenant must be a short slug' }, 400);
  let body: { visitorId?: unknown; shopperId?: unknown } = {};
  try { body = await c.req.json(); } catch { return c.json({ ok: false, error: 'invalid JSON body' }, 400); }
  const visitorId = typeof body.visitorId === 'string' ? body.visitorId.trim() : '';
  const shopperId = typeof body.shopperId === 'string' ? body.shopperId.trim() : '';
  if (!visitorId && !shopperId) return c.json({ ok: false, error: 'visitorId or shopperId required' }, 400);
  if (visitorId && !validVisitorId(visitorId)) return c.json({ ok: false, error: 'visitorId is not a visitor id' }, 400);
  if (shopperId && !isShopperId(shopperId)) return c.json({ ok: false, error: 'shopperId is not a shopper id' }, 400);
  const actor = (c as unknown as { get: (k: 'auth') => AuthContext | undefined }).get('auth')?.user?.sub ?? 'operator';
  const receipt = await eraseSubject(c.env, tenant, { ...(visitorId ? { visitorId } : {}), ...(shopperId ? { shopperId } : {}) }, actor);
  c.header('Cache-Control', 'no-store');
  return c.json({ ok: true, ...receipt });
});

import type { TenantVariables } from '@/tenancy/tenant';
import { shopperObject, shopperObjectName } from '@/tenancy/objects';
import { DEFAULT_TENANT, TenantKV, type KVLike } from '@/tenancy/tenant';
// Singleton objects: one per worker on purpose, never per brand.
const SINGLETON_ADMIN = 'admin';
const SINGLETON_HEALTH = 'health-check';
import { Hono } from 'hono';
import type { Env } from '@/types/env';
import { RealtimeSegmentEngine, type ActionEvent } from '@/services/RealtimeSegmentEngine';
import { getConnectors } from '@/connectors';
import { snapshot as reflexSnapshot } from '@/reflex/core';
import { resolveReflexConfig, resolveSurface } from '@/demos/registry';
import { forwardEventToOdp, mapActionToOdp, odpEnabled, upsertOdpProfile } from '@/services/odpLoop';
import { outcomeFromAction } from '@/ledger/records';
import { enqueueOutcome } from '@/ledger/enqueue';
import { consentFromCookies, consentOf } from '@/content/consent';
import { ACTION_EVENT_TYPES } from '@/events/actionTypes';
import { outcomeToLearning } from '@/learn/route';
import { CatalogService } from '@/services/CatalogService';
import { z } from 'zod';
import { requireShopper, shopperPrincipal, assertSessionTarget, privateShopperHeaders, SessionAccessError, newAnonymousSession } from '@/identity/sessionCapability';
import { SessionManager } from '@/services/SessionManager';

const realtimeRoutes = new Hono<{ Bindings: Env; Variables: TenantVariables }>();
for (const path of ['/ws', '/action', '/personalization/:userId', '/reflex', '/session/reset', '/session/:sessionId/preferences', '/session/:sessionId/analytics', '/segments/:userId', '/connections/:userId']) {
  realtimeRoutes.use(path, requireShopper());
}

// WebSocket upgrade endpoint
realtimeRoutes.get('/ws', async (c) => {
  const upgradeHeader = c.req.header('Upgrade');
  if (upgradeHeader !== 'websocket') {
    return c.text('Expected Upgrade: websocket', 426);
  }

  const userId = c.req.query('userId');
  if (!userId) {
    return c.text('Missing userId parameter', 400);
  }

  try {
    // Edge Affinity Reflex P2 (doc 16 §6): REFLEX_HOST='do' relocates the socket
    // INTO the per-shopper ShopperReflex DO — state + compute co-located, hot,
    // hibernating. `userId` is the STABLE visitor id the client persists
    // (opt_visitor_id), so every tab/device lands on the same object. Default
    // 'session' keeps the original relay DO — byte-identical behavior.
    if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
      const id = c.env.SHOPPER_REFLEX.idFromName(shopperObjectName(c.get('tenant'), userId));
      return c.env.SHOPPER_REFLEX.get(id).fetch(c.req.raw);
    }

    // Get the Durable Object instance for this user
    const id = c.env.PERSONALIZATION_WEBSOCKET.idFromName(shopperObjectName(c.get('tenant'), userId));
    const durableObject = c.env.PERSONALIZATION_WEBSOCKET.get(id);

    // Forward the WebSocket upgrade request to the Durable Object
    return durableObject.fetch(c.req.raw);
  } catch (error) {
      if (error instanceof SessionAccessError) throw error;
    console.error('Error establishing WebSocket connection');
    return c.text('Failed to establish WebSocket connection', 500);
  }
});

// Real-time action event processing.
// Retail event types ('product_view','add_to_cart','wishlist_add') are accepted
// alongside the original B2B types so the Coach storefront and existing callers
// share one ingestion path (REAL SEAMS, MOCKED CALLS — see docs/architecture/05-demo-build-spec.md §3).
export const actionEventSchema = z.object({
  // One list, in @/events/actionTypes, so this and the shopper object's door
  // cannot drift apart again (doc 31 §4: the object refused every content event).
  type: z.enum(ACTION_EVENT_TYPES),
  userId: z.string(),
  anonymousId: z.string().optional(),
  data: z.record(z.string(), z.any()),
  source: z.string(),
  // Which demo posted this (@/demos/registry). Optional and stripped-if-absent:
  // the engine falls back to `source`, and then to the default surface (coach),
  // so every existing client is unaffected.
  surface: z.string().optional(),
  // How the shopper arrived. Captured once per page load by the client and sent
  // with every action, because the server cannot know in advance which event
  // will be the one that opens a new visit. Optional, so every existing client
  // is unaffected and simply resolves to `direct`.
  entry: z.object({
    utmMedium: z.string().optional(),
    utmSource: z.string().optional(),
    referrer: z.string().optional(),
    siteHost: z.string().optional(),
  }).optional(),
  timestamp: z.number().optional()
});

realtimeRoutes.post('/action', async (c) => {
  try {
    const body = await c.req.json();
    assertSessionTarget(shopperPrincipal(c.req.raw), body?.userId, body?.sessionId);
    const validatedEvent = actionEventSchema.parse(body);

    // Add timestamp if not provided.
    // Cast: the zod schema accepts the retail event types ('product_view',
    // 'add_to_cart','wishlist_add'); ActionEvent['type'] is widened to the same
    // union by the catalog-aware engine refactor (build-spec §2.1/§2.2). The
    // runtime values are always valid events, so this stays correct post-refactor.
    const cfGeo = ((c.req.raw as unknown as { cf?: { country?: string; regionCode?: string } }).cf) ?? null;
    const actionEvent = {
      ...validatedEvent,
      anonymousId: shopperPrincipal(c.req.raw).kind === 'anonymous' ? shopperPrincipal(c.req.raw).subject : undefined,
      timestamp: validatedEvent.timestamp || Date.now(),
      // CW6: coarse request geolocation rides the event so the scoring host can
      // fan the touches into the shopper's region. Aggregates only, never stored per person.
      ...(cfGeo?.country ? { geo: { country: cfGeo.country, regionCode: cfGeo.regionCode ?? null } } : {}),
    } as ActionEvent;

    // Capture this demo-run event into D1 `demo_events` (source='demo'), kept
    // SEPARATE from the historical synthetic data so POST /operator/events/reset
    // can wipe ONLY these rows. Off the response path (waitUntil) so it adds zero
    // latency, and self-guarding so a D1 hiccup can never break the demo.
    const sessionId = typeof body.browsingSessionId === 'string' && body.browsingSessionId.trim()
      ? body.browsingSessionId.trim().slice(0, 128) : shopperPrincipal(c.req.raw).sessionId;
    // Phase 0 (doc 22 §3.2): a reward-bearing action becomes an outcome record, after the response.
    // The outcome's session must be the session the decision record carries, or session-scope
    // attribution compares two id spaces and credits nothing (found 2026-09-04). Both now prefer the
    // client's browsing session, which the SDK persists with an idle rule and sends on the snapshot and
    // on every event; a client that sends none gets the server's session on both. Called once the host
    // has answered, so the server's session is known.
    // CW31: a shopper who withheld tracking consent leaves no outcome anywhere. The object says so on its
    // envelope (`consent.tracking`); the session host mirrors the switch into the request's cookies.
    const emitOutcome = (serverSessionId: unknown, envelope?: Record<string, unknown>) => {
      const capture = captureDemoEvent(c.env, actionEvent, sessionId);
      try { c.executionCtx.waitUntil(capture); } catch { void capture; }
      const consent = consentOf({ consent: (envelope?.consent as { tracking?: unknown } | undefined) ?? null, preferences: { trackingConsent: consentFromCookies(c.req.header('Cookie')).tracking } });
      if (!consent.tracking) return;
      const server = typeof serverSessionId === 'string' && serverSessionId ? serverSessionId : undefined;
      const outcome = outcomeFromAction({ ...actionEvent, sessionId: sessionId ?? server }, c.get('tenant'));
      if (outcome) { const p = Promise.all([enqueueOutcome(c.env, outcome), outcomeToLearning(c.env, c.get('tenant'), outcome)]); try { c.executionCtx.waitUntil(p); } catch { void p; } }
    };

    // ── Edge Affinity Reflex P2 (doc 16 §6): REFLEX_HOST='do' forwards to the
    // shopper's ShopperReflex DO, which runs the same pipeline IN-OBJECT (reflex →
    // qualify → decide → push over its own socket) and returns the same envelope
    // shape ({success, update?, sessionId, cookiesUpdated, odp?}). The DO owns the
    // ODP loop on this path (forward + seed + receipt over its own socket), so no
    // route-level ODP dispatch here. The D1 captureDemoEvent above ran either way.
    const tEngine = performance.now();
    if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
      const stub = shopperObject(c.env.SHOPPER_REFLEX, actionEvent.userId, c.get('tenant'));
      const doRes = await stub.fetch('https://shopper-reflex/ingest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...privateShopperHeaders(c.req.raw) },
        body: JSON.stringify(actionEvent),
      });
      const out = (await doRes.json()) as Record<string, unknown>;
      c.header('Server-Timing', `object;dur=${Math.round(performance.now() - tEngine)}`);
      if (doRes.ok) emitOutcome(out.sessionId, out);
      return c.json(out, doRes.status as 200);
    }

    // Get cookie header for session management
    const cookieHeader = c.req.header('Cookie') ?? null;

    // CW31 (BTIE D10). The session host's own report of the shopper's switches:
    // SessionManager mirrors the two preferences into the request's cookies, so
    // the cookies are what this host knows before it has read the record. With
    // tracking off nothing about this request leaves the edge, which is the rule
    // the object host already holds in-object; the outcome is refused by
    // emitOutcome above and the two ODP dispatches below are refused here.
    const consent = consentFromCookies(cookieHeader);

    // Process the action event with enhanced session management
    const segmentEngine = new RealtimeSegmentEngine(c.env, getConnectors(c.env), { tenant: c.get('tenant'), principal: shopperPrincipal(c.req.raw) });
    let execCtx: { waitUntil(p: Promise<unknown>): void } | undefined;
    try { execCtx = c.executionCtx; } catch { execCtx = undefined; /* no execCtx (e.g. tests) */ }
    const result = await segmentEngine.processActionEventWithSession(actionEvent, cookieHeader, execCtx);
    // Where the time went: the engine's own work on the session host, for whoever is measuring.
    c.header('Server-Timing', `engine;dur=${Math.round(performance.now() - tEngine)}`);
    emitOutcome(result.sessionId);

    // ODP loop (doc 16 §8): forward the behavioral event to ODP OFF the response
    // path — the shopper never waits on the memory; ODP down = zero impact.
    // The response carries a dispatch RECEIPT (server truth: what the platform is
    // forwarding); the forwarder later pushes the ODP status over the WebSocket as
    // an `odp_receipt` so the feed row upgrades to its real ✓ 202.
    let odpReceipt: { receiptId: string; type: string; action?: string; product_id?: string } | undefined;
    if (consent.tracking && odpEnabled(c.env)) {
      const mapped = mapActionToOdp(actionEvent);
      if (mapped) {
        odpReceipt = {
          receiptId: crypto.randomUUID(),
          type: mapped.type,
          ...(mapped.action ? { action: mapped.action } : {}),
          ...(typeof mapped.data.product_id === 'string' ? { product_id: mapped.data.product_id } : {}),
        };
        c.executionCtx.waitUntil(forwardEventToOdp(
          c.env, actionEvent,
          { visitorId: actionEvent.userId, sessionId: result.sessionId },
          odpReceipt.receiptId,
          undefined,
          c.get('tenant'),
        ));
      }
      // §4 score upsert: on membership changes, persist the reflex's live scores
      // onto the ODP profile (the memory carrying the edge's numbers).
      const aff = result.update?.data?.affinity;
      if (aff && Array.isArray(aff.changed) && aff.changed.length > 0) {
        c.executionCtx.waitUntil(
          upsertOdpProfile(
            c.env,
            { visitorId: actionEvent.userId, sessionId: result.sessionId },
            aff, result.update?.data?.journeyStage,
          )
        );
      }
    }

    // Set updated cookies in response
    result.cookieHeaders.forEach(cookieHeader => {
      c.header('Set-Cookie', cookieHeader, { append: true });
    });

    if (result.update) {
      return c.json({
        success: true,
        message: 'Action processed and personalization updated',
        update: result.update,
        sessionId: result.sessionId,
        cookiesUpdated: result.cookieHeaders.length > 0,
        odp: odpReceipt
      });
    } else {
      return c.json({
        success: true,
        message: 'Action processed, no personalization changes needed',
        sessionId: result.sessionId,
        cookiesUpdated: result.cookieHeaders.length > 0,
        odp: odpReceipt
      });
    }

  } catch (error) {
      if (error instanceof SessionAccessError) throw error;
    console.error('Error processing action event');

    if (error instanceof z.ZodError) {
      return c.json({
        error: 'Invalid action event format',
        details: error.issues
      }, 400);
    }

    return c.json({
      error: 'Failed to process action event',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, 500);
  }
});

// Get personalization config with session management
realtimeRoutes.get('/personalization/:userId', async (c) => {
  try {
    const userId = c.req.param('userId');
    if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
      const response = await shopperObject(c.env.SHOPPER_REFLEX, shopperPrincipal(c.req.raw).subject, c.get('tenant')).fetch('https://shopper-reflex/personalization', { headers: privateShopperHeaders(c.req.raw) });
      return new Response(response.body, response);
    }

    if (!userId) {
      return c.json({ error: 'User ID is required' }, 400);
    }

    const cookieHeader = c.req.header('Cookie') ?? null;
    const segmentEngine = new RealtimeSegmentEngine(c.env, getConnectors(c.env), { tenant: c.get('tenant'), principal: shopperPrincipal(c.req.raw) });

    // Get or create session from cookies
    const { sessionId, sessionData, isNewSession } = await segmentEngine.getOrCreateSessionFromCookies(
      cookieHeader,
      userId
    );

    // Get personalization configuration
    const config = await segmentEngine.getSessionPersonalizationConfig(sessionId);

    if (!config) {
      return c.json({ error: 'Failed to get personalization configuration' }, 500);
    }

    // Set cookies in response
    config.cookieHeaders.forEach(cookieHeader => {
      c.header('Set-Cookie', cookieHeader, { append: true });
    });

    return c.json({
      userId,
      sessionId,
      isNewSession,
      config: {
        segments: config.segments,
        featureFlags: config.featureFlags,
        featureVariables: config.featureVariables,
        experiments: config.experiments
      },
      cookiesSet: config.cookieHeaders.length > 0,
      timestamp: Date.now()
    });

  } catch (error) {
      if (error instanceof SessionAccessError) throw error;
    console.error('Error getting personalization config');
    return c.json({
      error: 'Failed to get personalization configuration',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, 500);
  }
});

// Edge Affinity Reflex — hydrate snapshot for the Affinity Instrument (doc 16 §10).
// Resolves the shopper's session from cookies and returns freshly-computed live
// affinity (scores decay by construction, so they are ALWAYS computed at read).
realtimeRoutes.get('/reflex', async (c) => {
  try {
    const cookieHeader = c.req.header('Cookie') ?? null;
    const userId = shopperPrincipal(c.req.raw).subject;

    // REFLEX_HOST='do' (doc 16 §6): the vector lives in the shopper's own
    // ShopperReflex DO — read the snapshot there (same response shape).
    if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
      const stub = shopperObject(c.env.SHOPPER_REFLEX, userId, c.get('tenant'));
      const doRes = await stub.fetch('https://shopper-reflex/snapshot', { headers: privateShopperHeaders(c.req.raw) });
      return c.json((await doRes.json()) as Record<string, unknown>, doRes.status as 200);
    }

    const segmentEngine = new RealtimeSegmentEngine(c.env, getConnectors(c.env), { tenant: c.get('tenant'), principal: shopperPrincipal(c.req.raw) });
    const { sessionData } = await segmentEngine.getOrCreateSessionFromCookies(cookieHeader, userId);
    // Surface-aware tuning (@/demos/registry): an explicit ?surface= wins, else
    // the session remembers which demo it belongs to, else DEFAULT_SURFACE.
    // With both absent and nothing stored, this resolves to
    // DEFAULT_REFLEX_CONFIG BY IDENTITY — every pre-existing caller gets a
    // byte-identical response until someone tunes the scope.
    const cfg = await resolveReflexConfig(
      c.env,
      resolveSurface({ surface: c.req.query('surface') ?? sessionData.surface })
    );
    const now = Date.now();
    return c.json({
      ok: true,
      now,
      config: {
        tauMs: cfg.tauMs,
        K: cfg.K,
        thetaIn: cfg.thetaIn,
        thetaOut: cfg.thetaOut,
        // Per-dimension overrides (e.g. priceBand's slower τ) so the client's
        // honest drain animation decays each bar at its TRUE rate.
        dims: Object.fromEntries(
          cfg.dimensions
            .filter((d) => d.tauMs || d.K || d.thetaIn || d.thetaOut)
            .map((d) => [d.key, { tauMs: d.tauMs, K: d.K, thetaIn: d.thetaIn, thetaOut: d.thetaOut }])
        ),
      },
      affinity: sessionData.reflex
        ? { ...reflexSnapshot(sessionData.reflex, now, cfg), odpConfirmed: sessionData.odpSeed ?? [] }
        : null,
    });
  } catch (error) {
      if (error instanceof SessionAccessError) throw error;
    return c.json(
      { ok: false, error: error instanceof Error ? error.message : 'reflex snapshot failed' },
      500
    );
  }
});

// New shopper — expire the session cookies (opt_session_id is HttpOnly, so only the
// server can clear it) and drop the KV session. The next page load cold-starts clean:
// fresh reflex, fresh journey, geo cold-start hero. Powers the "New shopper" button
// so presenters restart WITHOUT hunting for an incognito window.
realtimeRoutes.post('/session/reset', async (c) => {
  const principal = shopperPrincipal(c.req.raw);
  if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
    const result = await shopperObject(c.env.SHOPPER_REFLEX, principal.subject, principal.tenant).fetch('https://shopper-reflex/reset', { method: 'POST', headers: privateShopperHeaders(c.req.raw) });
    if (!result.ok) throw new SessionAccessError();
  } else {
    const sm = new SessionManager(c.env, { tenant: principal.tenant, principal });
    if (!await sm.deleteSession(principal.sessionId)) throw new SessionAccessError();
  }
  // Expire every opt_* cookie the SessionManager sets (superset — extras are harmless).
  const names = [
    'opt_session_id', 'opt_user_id', 'opt_anonymous_id', 'opt_segments',
    'opt_engagement_score', 'opt_last_update', 'opt_tracking_consent', 'opt_personalization_enabled',
  ];
  for (const name of names) {
    c.header('Set-Cookie', `${name}=; Max-Age=0; Path=/; SameSite=Lax`, { append: true });
  }
  return c.json({ ok: true, cleared: true, session: await newAnonymousSession(c.env, principal.tenant) });
});

// Session preferences management
const preferencesSchema = z.object({
  trackingConsent: z.boolean().optional(),
  personalizationEnabled: z.boolean().optional(),
  cookieConsent: z.boolean().optional(),
  // CW31: on the object host the switches live on the shopper's object, which is named by the visitor id.
  userId: z.string().trim().min(1).max(200).optional(),
});

realtimeRoutes.post('/session/:sessionId/preferences', async (c) => {
  try {
    const sessionId = c.req.param('sessionId');
    const body = await c.req.json();
    const preferences = preferencesSchema.parse(body);
    const principal = shopperPrincipal(c.req.raw);
    assertSessionTarget(principal, preferences.userId, sessionId);

    if (!sessionId) {
      return c.json({ error: 'Session ID is required' }, 400);
    }

    // CW31: the object host keeps the switches on the shopper's object; tell it, off the response path.
    if ((c.env.REFLEX_HOST ?? 'session') === 'do') {
      const told = await shopperObject(c.env.SHOPPER_REFLEX, principal.subject, principal.tenant).fetch('https://shopper-reflex/consent', {
        method: 'POST', headers: { 'Content-Type': 'application/json', ...privateShopperHeaders(c.req.raw) },
        body: JSON.stringify({ tracking: preferences.trackingConsent, personalization: preferences.personalizationEnabled }),
      });
      if (!told.ok) throw new SessionAccessError();
      return c.json({ success: true, sessionId, preferences, cookiesUpdated: false, timestamp: Date.now() });
    }

    const segmentEngine = new RealtimeSegmentEngine(c.env, getConnectors(c.env), { tenant: c.get('tenant'), principal: shopperPrincipal(c.req.raw) });
    const updatedSession = await segmentEngine.updateSessionPreferences(sessionId, preferences);

    if (!updatedSession) {
      return c.json({ error: 'Session not found' }, 404);
    }

    // Generate updated cookies
    const cookies = await segmentEngine.getSessionPersonalizationConfig(sessionId);
    if (cookies) {
      cookies.cookieHeaders.forEach(cookieHeader => {
        c.header('Set-Cookie', cookieHeader, { append: true });
      });
    }

    return c.json({
      success: true,
      sessionId,
      preferences: updatedSession.preferences,
      cookiesUpdated: cookies?.cookieHeaders.length || 0 > 0,
      timestamp: Date.now()
    });

  } catch (error) {
      if (error instanceof SessionAccessError) throw error;
    console.error('Error updating session preferences');

    if (error instanceof z.ZodError) {
      return c.json({
        error: 'Invalid preferences format',
        details: error.issues
      }, 400);
    }

    return c.json({
      error: 'Failed to update session preferences',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, 500);
  }
});

