/**
 * Storage key `'affinity'` — exactly the record doc 16 §6 / the P2 spec mandates.
 * `reflex` is raw (R, tLast) per dimension·value — NEVER pre-decayed (§4).
 */
export interface AffinityRecord {
  shopperId: string;
  reflex: ReflexState;
  odpSeed: string[];
  odpSeedAt: number;
  odpRecentEvents: Array<Record<string, unknown>>;
  lastSeen: number;
  configVersion: string;
}

/**
 * Storage key `'pipeline'` — the DO-side companion record that lets ingest() run
 * the SAME pipeline as the request path (behavioral counters → journey stage →
 * qualification → decisions). Kept under a SEPARATE key so `'affinity'` stays
 * byte-shaped to the spec. (Documented deviation: doc 16 §6 lists only the
 * affinity record; without these the DO could not qualify the counter-based seed
 * audiences or derive the journey stage the request path derives.)
 */
export interface PipelineRecord {
  attributes: Record<string, any>;
  segments: string[];
  journeyStage: 'early' | 'mid' | 'late';
  /** DO-held session id. No longer what the ODP vuid derives from — see visitorId. */
  sessionId: string;
  /**
   * The stable first-party visitor id (`opt_visitor_id`), which is also the name
   * this object is keyed on. Persisted for the same reason `surface` is: the
   * alarm and snapshot paths run with no event to resolve it from, and the ODP
   * vuid must not change just because a write happened on one of those paths.
   * ABSENT on records written before the CW7b cutover; those fall back to the
   * session id and keep exactly the identity they already had.
   */
  visitorId?: string;
  firstSeen: number;
  sessionCount: number;
  /** Demo surface this shopper object belongs to (@/demos/registry). ABSENT ⇒
      'coach' — every record written before the multi-surface split is retail's.
      Persisted because the alarm/snapshot paths have no event to resolve from. */
  surface?: DemoSurface;
}

interface IngestOutcome {
  status: number;
  body: Record<string, unknown>;
  update: PersonalizationUpdate | null;
}

/**
 * Event types accepted at this object's doors. The same list POST /realtime/action
 * validates against, imported rather than restated: this Set used to be written
 * out here beside a comment asking it to stay in step, and it did not. It was
 * missing `purchase` and all four content events, so the object answered 400 to
 * every content click and staging stayed on the slower session host (doc 31 §4).
 */
const ACTION_EVENT_TYPES = ACTION_EVENT_TYPE_SET;

/** Never set an alarm in the past; give the current event a beat to settle. */
const MIN_ALARM_DELAY_MS = 50;

/** Cheap per-minute in-DO rate limit (doc 16 §12) — override with REFLEX_RATE_LIMIT_PER_MIN. */
const DEFAULT_RATE_LIMIT_PER_MIN = 240;

const DEFAULT_RETENTION_DAYS = 30;

/**
 * Closed-form alarm time (doc 16 §6): the earlier of
 *   • the exact instant the earliest CURRENT membership decays below θ_out
 *     (core's nextCrossing — t* = tLast + τ·ln(R·(1−θ_out)/(K·θ_out))), and
 *   • the retention horizon (lastSeen + retentionMs — idle self-expiry, §12),
 * clamped to now+MIN_ALARM_DELAY_MS so a boundary crossing fires immediately but
 * never busy-loops. Pure — exported for the P2 test suite.
 */
export function computeNextAlarm(
  reflex: ReflexState,
  lastSeen: number,
  now: number,
  config: ReflexConfig,
  retentionMs: number
): number {
  const crossing = nextCrossing(reflex, now, config);
  const retentionAt = lastSeen + retentionMs;
  const at = crossing === null ? retentionAt : Math.min(crossing, retentionAt);
  return Math.max(at, now + MIN_ALARM_DELAY_MS);
}

// One catalog per isolate — the item-item graph precompute never runs per event.
let _catalog: CatalogService | null = null;
function catalog(): CatalogService {
  return (_catalog = _catalog ?? new CatalogService());
}

/**
 * The catalog a surface scores against. The default surface keeps the isolate-wide
 * instance above (same object, same graph); other surfaces resolve their own
 * memoized CatalogService from the registry — this is what makes the trust gate
 * below surface-aware instead of dropping every foreign product id (P4).
 */
async function catalogFor(surface: DemoSurface): Promise<CatalogService> {
  return surface === DEFAULT_SURFACE ? catalog() : catalogServiceFor(surface);
}

export class ShopperReflex {
  private state: DurableObjectState;
  /** CW25. The NAME of the person's object this browser's object forwards to; undefined until read. */
  private forwardTo: string | null | undefined = undefined;
  /**
   * CW31. The shopper's two consent switches, stored under their own key so the
   * instruction survives when nothing else may be written. Absent means
   * consenting. undefined until read.
   */
  private consent: { tracking: boolean; personalization: boolean } | null | undefined = undefined;
  private env: Env;

  /** In-memory mirrors of storage; rehydrated from ctx.storage on wake. */
  private affinity: AffinityRecord | null = null;
  private pipeline: PipelineRecord | null = null;
  private loaded = false;
  private seeded = new Set<DemoSurface>();

  /** Serializes ingest/alarm runs — the reducer is strictly sequential even when
      awaits on KV/ODP would otherwise let events interleave. */
  private chain: Promise<unknown> = Promise.resolve();

  /** Cheap per-minute rate limit. In-memory by design (zero storage writes): a
      hibernation wake resets it, but sustained bursts — the abuse case — keep the
      object alive, so the window holds exactly when it matters. */
  private rate = { windowStart: 0, count: 0 };
  private dropped = { rateLimited: 0, unknownProduct: 0, invalid: 0 };

  constructor(state: DurableObjectState, env: Env) {
    this.state = state;
    this.env = env;
  }

  // ── HTTP surface ────────────────────────────────────────────────────────────

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    let principal: SessionCapability | undefined;
    if (capabilityToken(request) !== null || request.headers.get('Upgrade') === 'websocket') {
      try {
        principal = await verifySessionCapability(this.env, capabilityToken(request), shopperTenant(this.env, request));
        assertSessionTarget(principal, url.searchParams.get('userId'), url.searchParams.get('sessionId'));
        if (this.state.id.toString() !== this.env.SHOPPER_REFLEX.idFromName(shopperObjectName(principal.tenant, principal.subject)).toString()) throw new SessionAccessError();
      } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
    }

    if (request.headers.get('Upgrade') === 'websocket') {
      return this.serialize(async () => {
        try { await this.assertOwned(principal!, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        return this.handleUpgrade(url, principal!);
      });
    }
    if (principal && ['/personalization', '/segments', '/analytics'].includes(url.pathname)) {
      const p = principal;
      return this.serialize(async () => {
        try { await this.assertOwned(p, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        const now = Date.now();
        if (url.pathname === '/analytics') return json({ sessionId: p.sessionId, analytics: {
          sessionDuration: this.pipeline ? now - this.pipeline.firstSeen : 0,
          pageViews: this.pipeline?.attributes.page_views ?? 0,
          engagementScore: calculateEngagementScore(this.pipeline?.attributes ?? {}), segmentHistory: this.pipeline?.segments ?? [],
        }, timestamp: now });
        const connectors = getConnectors(this.env);
        if (url.pathname === '/segments') {
          if (request.method === 'POST') {
            const consent = await this.consentNow();
            if (!consent.tracking || !consent.personalization) return json({ ok: false, error: 'Shopper consent refused segment assignment' }, 403);
            const body = await request.json() as { segment?: unknown; source?: unknown };
            if (typeof body.segment !== 'string') return json({ ok: false, error: 'segment required' }, 400);
            const cfg = await resolveReflexConfig(this.env, this.surface());
            this.affinity ??= { shopperId: p.subject, reflex: emptyState(cfg), odpSeed: [], odpSeedAt: 0, odpRecentEvents: [], lastSeen: now, configVersion: cfg.version };
            this.pipeline ??= { attributes: {}, segments: [], journeyStage: 'early', sessionId: p.sessionId, visitorId: p.subject, firstSeen: now, sessionCount: 0 };
            this.pipeline.segments = [...new Set([...this.pipeline.segments, body.segment])];
            await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
            const update = await this.buildUpdate(connectors, now, typeof body.source === 'string' ? body.source : 'manual', null, calculateEngagementScore(this.pipeline.attributes));
            this.pushFrame(update);
            return json({ success: true, userId: p.subject, segment: body.segment, timestamp: now });
          }
          await this.ensureSeeded(this.surface());
          const segments = await connectors.segments.fetchQualifiedSegments(p.subject, {
            userId: p.subject, attributes: { ...RETAIL_SIGNAL_DEFAULTS, ...this.pipeline?.attributes }, segments: this.pipeline?.segments ?? [], surface: this.surface(),
          });
          return json({ userId: p.subject, segments, timestamp: now });
        }
        const consent = await this.consentNow();
        const update = this.affinity && this.pipeline && consent.tracking && consent.personalization
          ? await this.buildUpdate(connectors, now, 'snapshot', null, calculateEngagementScore(this.pipeline.attributes)) : null;
        return json({ userId: p.subject, sessionId: p.sessionId, isNewSession: !this.pipeline, config: {
          segments: this.pipeline?.segments ?? [], featureVariables: update?.data.featureVariables ?? {},
          featureFlags: Object.fromEntries(Object.entries(update?.data.decisions ?? {}).map(([key, decision]) => [key, decision.enabled])),
          experiments: Object.fromEntries(Object.entries(update?.data.decisions ?? {}).filter(([, decision]) => decision.variationKey).map(([key, decision]) => [key, decision.variationKey])),
        }, cookiesSet: false, timestamp: now });
      });
    }

    // CW25. A browser that was recognised forwards to the person's object: the
    // same ingest, the same snapshot, one hop. Nothing else is forwarded; the
    // identity doors below act on THIS object by design.
    if (!principal && (url.pathname === '/ingest' || url.pathname === '/snapshot')) {
      const forwarded = await this.forwardIfLinked(request);
      if (forwarded) return forwarded;
    }
    if (request.method === 'POST' && url.pathname === '/ingest') {
      return this.handleIngest(request, principal);
    }
    if (request.method === 'GET' && url.pathname === '/snapshot') {
      return this.serialize(async () => {
        try { if (principal) await this.assertOwned(principal, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        return this.handleSnapshot();
      });
    }
    // CW25, the identity doors. `export` reads what this browser learned;
    // `absorb` folds another object's export into this one, which then IS the
    // person; `forward` leaves this object pointing at the person's.
    if (request.method === 'GET' && url.pathname === '/identity/export') {
      return this.serialize(async () => {
        try { if (principal) await this.assertOwned(principal, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        await this.load();
        return json({ ok: true, affinity: this.affinity, pipeline: this.pipeline, forwardTo: await this.forwardTarget() });
      });
    }
    if (request.method === 'POST' && url.pathname === '/identity/absorb') {
      return this.handleAbsorb(request);
    }
    if (request.method === 'POST' && url.pathname === '/identity/import') {
      return this.handleImport(request);
    }
    // CW31. The shopper's consent switches, as the site reports them. This is the
    // one write that happens even when tracking is off: it is the instruction
    // not to write, and it has to be remembered to be honoured.
    if (request.method === 'POST' && url.pathname === '/consent') {
      let body: { tracking?: unknown; personalization?: unknown } = {};
      try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
      return this.serialize(async () => {
        try { if (principal) await this.assertOwned(principal, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        const consent = await this.setConsent(body);
        return json({ ok: true, consent });
      });
    }
    if (request.method === 'POST' && url.pathname === '/identity/forward') {
      let body: { to?: unknown } = {};
      try { body = await request.json(); } catch { /* fallthrough */ }
      if (typeof body.to !== 'string' || body.to === '') return json({ ok: false, error: 'to required' }, 400);
      await this.serialize(async () => {
        await this.state.storage.put('forwardTo', body.to);
        this.forwardTo = body.to as string;
      });
      return json({ ok: true, forwardTo: body.to });
    }
    if (request.method === 'GET' && url.pathname === '/health') {
      await this.load();
      return json({
        status: 'healthy',
        shopperId: this.affinity?.shopperId ?? null,
        sockets: this.state.getWebSockets().length,
        audiences: this.affinity?.reflex.audiences ?? [],
        lastSeen: this.affinity?.lastSeen ?? null,
        dropped: this.dropped,
      });
    }
    // Erasure door (§12 privacy/lifecycle): wipes the vector + memberships.
    // GDPR/CCPA path and the operator's hard reset; retention uses the same wipe.
    if (request.method === 'POST' && url.pathname === '/reset') {
      return this.serialize(async () => {
        try { if (principal) await this.assertOwned(principal, request); } catch { return json({ ok: false, error: 'Shopper session unavailable' }, 401); }
        await this.state.storage.deleteAll();
        this.affinity = null;
        this.pipeline = null;
        this.forwardTo = null;
        this.consent = null;
        this.loaded = true;
        return json({ ok: true });
      });
    }

    return new Response('Not Found', { status: 404 });
  }

  // ── Door 1: the WebSocket (Hibernation API) ─────────────────────────────────

  private async handleUpgrade(url: URL, principal: SessionCapability): Promise<Response> {
    const shopperId = url.searchParams.get('userId');
    if (!shopperId) {
      return new Response('Missing userId parameter', { status: 400 });
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);

    // Hibernation accept: the runtime may evict this object between messages and
    // wake it on the next frame — near-zero idle cost, sockets stay connected.
    this.state.acceptWebSocket(server);
    // HARD RULE: the attachment carries ONLY {shopperId} (~2KB cap). All affinity
    // state lives in ctx.storage and rehydrates via load() on wake.
    server.serializeAttachment({ shopperId, principal });

    // Same welcome frame the relay DO sends — client transport code is unchanged.
    server.send(
      JSON.stringify({
        type: 'connected',
        connectionId: crypto.randomUUID(),
        userId: shopperId,
        timestamp: Date.now(),
      })
    );

    return new Response(null, { status: 101, webSocket: client, headers: { 'Sec-WebSocket-Protocol': SHOPPER_PROTOCOL } });
  }

  /** Hibernation handler — wakes the object on any client frame. */
  async webSocketMessage(ws: WebSocket, message: string | ArrayBuffer): Promise<void> {
    if (typeof message !== 'string') return;
    let frame: any;
    try {
      frame = JSON.parse(message);
    } catch {
      return;
    }
    if (!frame || typeof frame !== 'object') return;
    const attachment = (safeAttachment(ws) ?? {}) as { shopperId?: string; principal?: SessionCapability };
    try {
      if (!attachment.principal) throw new SessionAccessError();
      assertSessionTarget(attachment.principal, frame.userId, frame.sessionId);
      if (frame.event) assertSessionTarget(attachment.principal, frame.event.userId, frame.event.sessionId);
    } catch { ws.close(1008, 'Shopper session unavailable'); return; }

    if (frame.type === 'heartbeat') {
      try {
        ws.send(JSON.stringify({ type: 'heartbeat_response', timestamp: Date.now() }));
      } catch { /* dying socket — close handler cleans up */ }
      return;
    }

    if (frame.type !== 'action') return; // subscribe/unsubscribe etc. — no-ops here

    const event = this.normalizeEvent(frame, attachment.shopperId);
    if (!event) {
      this.dropped.invalid++;
      return;
    }
    // Same reducer as POST /ingest; the outcome reaches the client as the push
    // this ingest emits over the DO's own sockets (no HTTP response on this door).
    await this.serialize(async () => {
      try { await this.assertOwned(attachment.principal!); assertSessionTarget(attachment.principal!, event.userId); }
      catch { ws.close(1008, 'Shopper session unavailable'); return; }
      return this.ingest(event, attachment.principal);
    });
  }

  async webSocketClose(_ws: WebSocket, _code: number, _reason: string, _wasClean: boolean): Promise<void> {
    // Nothing to clean: connection bookkeeping IS state.getWebSockets(); shopper
    // state persists in storage; the pending alarm keeps decay-out + retention live.
  }

  async webSocketError(_ws: WebSocket, error: unknown): Promise<void> {
    console.error('ShopperReflex webSocketError');
  }

  // ── Door 2: POST /ingest ────────────────────────────────────────────────────

  private async handleIngest(request: Request, principal?: SessionCapability): Promise<Response> {
    let body: any;
    try {
      body = await request.json();
    } catch {
      return json({ success: false, error: 'invalid JSON body' }, 400);
    }
    const event = this.normalizeEvent(body, undefined);
    if (!event) {
      this.dropped.invalid++;
      return json({ success: false, error: 'invalid action event' }, 400);
    }
    const outcome = await this.serialize(async () => {
      try {
        if (principal) { assertSessionTarget(principal, event.userId, body.sessionId); await this.assertOwned(principal, request); }
      } catch { return { body: { success: false, error: 'Shopper session unavailable' }, status: 401, update: null }; }
      return this.ingest(event, principal);
    });
    return json(outcome.body, outcome.status);
  }

  /**
   * Accept either a bare ActionEvent (the POST /realtime/action body shape) or a
   * WS frame `{type:'action', event:{…}}` / flattened `{type:'action', action, data}`.
   */
  private normalizeEvent(raw: any, fallbackShopperId?: string): ActionEvent | null {
    const src = raw && typeof raw === 'object' && raw.event && typeof raw.event === 'object' ? raw.event : raw;
    if (!src || typeof src !== 'object') return null;

    const type =
      typeof src.type === 'string' && ACTION_EVENT_TYPES.has(src.type)
        ? src.type
        : typeof src.action === 'string' && ACTION_EVENT_TYPES.has(src.action)
          ? src.action
          : null;
    if (!type) return null;

    const userId = typeof src.userId === 'string' && src.userId ? src.userId : fallbackShopperId;
    if (!userId) return null;

    return {
      type: type as ActionEvent['type'],
      userId,
      ...(typeof src.anonymousId === 'string' ? { anonymousId: src.anonymousId } : {}),
      data: src.data && typeof src.data === 'object' ? src.data : {},
      source: typeof src.source === 'string' ? src.source : 'ws',
      ...(typeof src.surface === 'string' ? { surface: src.surface } : {}),
      // Advisory only — ingest() stamps its own arrival time (§4).
      timestamp: typeof src.timestamp === 'number' ? src.timestamp : Date.now(),
    };
  }

  // ── THE reducer: one handler behind both doors ──────────────────────────────

  private async ingest(event: ActionEvent, principal?: SessionCapability): Promise<IngestOutcome> {
    // The ENGINE clock is authoritative — a forged/skewed client clock cannot
    // inflate affinity (doc 16 §4). Everything downstream uses this stamp.
    const now = Date.now();

    if (!this.allowIngest(now)) {
      this.dropped.rateLimited++;
      return {
        status: 429,
        body: { success: false, error: 'rate_limited', retryAfterMs: this.rate.windowStart + 60_000 - now },
        update: null,
      };
    }

    // Which demo posted this — resolved from the event alone (explicit field, else
    // `source`, else coach), so the trust gate below can consult the RIGHT catalog
    // before any storage read.
    const surface = resolveSurface({
      source: event.source,
      surface: event.surface ?? (event.data as Record<string, unknown> | undefined)?.surface as string | undefined,
    });
    const surfaceCatalog = await catalogFor(surface);
    const cfg = await resolveReflexConfig(this.env, surface);

    // Trust & abuse (§12): validate referenced products against the in-memory
    // catalog index — an unknown productId is dropped and counted, never scored.
    const data = event.data ?? {};
    const pid = data.productId ?? data.product_id ?? data.sku;
    const product = pid != null ? surfaceCatalog.getProduct(String(pid)) : undefined;
    // CW24: where the scope scores event-carried attributes, an unknown id with
    // registry attributes on it is a customer's product, not an abuse attempt.
    const eventTouches = !product && cfg.eventAttributes === 'event-when-unknown'
      ? touchesForEvent(data as Record<string, unknown>, undefined, cfg) : [];
    if (pid != null && !product && eventTouches.length === 0) {
      this.dropped.unknownProduct++;
      return {
        status: 200,
        body: {
          success: true,
          message: 'Action ignored: unknown productId',
          dropped: 'unknown_product',
          sessionId: this.pipeline?.sessionId ?? null,
          cookiesUpdated: false,
          consent: await this.consentNow(),
        },
        update: null,
      };
    }

    await this.load();
    await this.ensureSeeded(surface);
    const connectors = getConnectors(this.env); // fresh per run — mirrors the per-request triad

    // CW31. An event may carry the switches (`data.consent`); a change is
    // remembered before anything else happens. With tracking off, the pipeline
    // still answers this request from the state it has, but nothing it computes
    // is kept, forwarded or persisted: the object is restored to what it was.
    const eventConsent = data.consent;
    const consent = eventConsent && typeof eventConsent === 'object'
      ? await this.setConsent(eventConsent as { tracking?: unknown; personalization?: unknown })
      : await this.consentNow();
    const before = consent.tracking ? null : { affinity: structuredClone(this.affinity), pipeline: structuredClone(this.pipeline) };

    const aff: AffinityRecord = this.affinity ?? {
      shopperId: event.userId,
      reflex: emptyState(cfg),
      odpSeed: [],
      odpSeedAt: 0,
      odpRecentEvents: [],
      lastSeen: now,
      configVersion: cfg.version,
    };
    const pipe: PipelineRecord = this.pipeline ?? {
      attributes: {},
      segments: [],
      journeyStage: 'early',
      sessionId: principal?.sessionId ?? crypto.randomUUID(),
      firstSeen: now,
      sessionCount: 0,
      // Only non-default surfaces are tagged, so a retail record's stored bytes
      // are exactly what they were before the split.
      ...(surface === DEFAULT_SURFACE ? {} : { surface }),
    };

    // The stable id rides in on every event as `userId`. Recorded once and kept,
    // so a later alarm or snapshot resolves the same vuid as a live event would.
    if (!pipe.visitorId && typeof event.userId === 'string' && event.userId !== '') {
      pipe.visitorId = event.userId;
    }

    // 1. Behavioral counters — the SAME accrual the request path runs.
    const attributes = { ...pipe.attributes };
    applyEventToAttributes(attributes, event, surfaceCatalog);
    const engagementScore = calculateEngagementScore(attributes);

    // 2. The pure core (§4): decay-then-accumulate + hysteresis evaluation.
    const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';
    let reflex: ReflexResult | null = null;
    if (reflexOn) {
      const action = actionOf(event);
      reflex = applyReflex(
        aff.reflex,
        {
          action,
          touches: isContentAction(action)
            ? contentTouches(data as Record<string, unknown>, cfg)
            : product ? extractTouches(product as unknown as Record<string, unknown>, cfg) : eventTouches,
        },
        now,
        cfg
      );
      // CW6: the same touches, fanned into the shopper's region as a population count.
      // Registered with the object's own waitUntil so the call survives the reply.
      const keepAlive = (p: Promise<unknown>) => { try { (this.state as unknown as { waitUntil?: (p: Promise<unknown>) => void }).waitUntil?.(p); } catch { /* older runtime */ } };
      keepAlive(fanInRegionTrend(this.env, {
        tenant: surface, geo: (event as { geo?: { country?: string | null; regionCode?: string | null } }).geo, now,
        touches: product ? extractTouches(product as unknown as Record<string, unknown>, cfg) : eventTouches,
        w: cfg.weights[action] ?? 0,
      }));
    }

    // 3. Local qualification through the ODP seam (KvAudienceStore + evaluateCondition).
    const ctxAttrs: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...attributes };
    const qualCtx = {
      userId: aff.shopperId,
      anonymousId: event.anonymousId,
      attributes: ctxAttrs,
      segments: pipe.segments,
      surface, // qualification evaluates only THIS surface's audiences
    };
    const journeyStage = deriveStage(qualCtx);
    ctxAttrs.journey_stage = journeyStage;
    // Reflex scores are computed FRESH into the context (they decay by construction —
    // never persisted), so store-published affinity audiences can gte them.
    if (reflex) Object.assign(ctxAttrs, reflexAttributes(reflex.state, now, cfg));
    let localSegments: string[] = [];
    try {
      localSegments = await connectors.segments.fetchQualifiedSegments(aff.shopperId, qualCtx);
    } catch (e) {
      console.error('ShopperReflex qualification failed (degrading to reflex-only)');
    }

    // 4. ODP loop (§8) — same ring + seed policy as the request path (shared fns).
    let odpSeed = aff.odpSeed;
    let odpSeedAt = aff.odpSeedAt;
    let odpRing = aff.odpRecentEvents.slice();
    let odpReceipt: { receiptId: string; type: string; action?: string; product_id?: string } | undefined;
    const membershipChanged = !!reflex && (reflex.changes.entered.length > 0 || reflex.changes.exited.length > 0);
    if (odpEnabled(this.env)) {
      odpRing = updateOdpRing(odpRing, event, now);
      ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
        this.env,
        { visitorId: pipe.visitorId, sessionId: pipe.sessionId },
        odpRing,
        { seed: odpSeed, seedAt: odpSeedAt },
        now,
        membershipChanged
      ));
      // Forward to the memory OFF the hot path. Fire-and-forget: a DO stays alive
      // while I/O is in flight, and forwardEventToOdp never throws. The receipt
      // lands over THIS object's own sockets — no relay hop.
      const mapped = mapActionToOdp(event);
      if (mapped) {
        odpReceipt = {
          receiptId: crypto.randomUUID(),
          type: mapped.type,
          ...(mapped.action ? { action: mapped.action } : {}),
          ...(typeof mapped.data.product_id === 'string' ? { product_id: mapped.data.product_id } : {}),
        };
        if (consent.tracking) {
          void forwardEventToOdp(this.env, event, { visitorId: pipe.visitorId, sessionId: pipe.sessionId }, odpReceipt.receiptId, (receipt) =>
            this.pushFrame({ type: 'odp_receipt', userId: aff.shopperId, data: receipt })
          );
        } else {
          odpReceipt = undefined;   // nothing left the edge
        }
      }
    }

    // 5. Union (local ∪ reflex ∪ ODP seed) + change detection — same triggers.
    // The surface namespace is applied to the core's membership keys here so they
    // match the generated audience keys (prefix '' for coach ⇒ same array).
    const prefix = audienceKeyPrefixFor(surface);
    const reflexAudiences = reflex
      ? prefix
        ? reflex.state.audiences.map((k) => prefix + k)
        : reflex.state.audiences
      : [];
    const newSegments = Array.from(
      new Set([...localSegments, ...reflexAudiences, ...odpSeed])
    );
    const segmentsChanged = hasSegmentChanges(pipe.segments, newSegments);
    const stageChanged = pipe.journeyStage !== journeyStage;

    // 6. Commit the new records to the in-memory mirrors.
    this.affinity = {
      shopperId: aff.shopperId,
      reflex: reflex ? reflex.state : aff.reflex,
      odpSeed,
      odpSeedAt,
      odpRecentEvents: odpRing,
      lastSeen: now,
      configVersion: cfg.version,
    };
    this.pipeline = {
      attributes,
      segments: newSegments,
      journeyStage,
      sessionId: pipe.sessionId,
      firstSeen: pipe.firstSeen,
      sessionCount: pipe.sessionCount + 1,
      ...(surface === DEFAULT_SURFACE ? {} : { surface }),
    };

    // 7. Changed? → decide + push over the DO's OWN sockets, in the same object.
    let update: PersonalizationUpdate | null = null;
    if (segmentsChanged || stageChanged) {
      update = await this.buildUpdate(connectors, now, event.source, reflex, engagementScore);
      this.pushFrame({ ...update, serverTimestamp: Date.now() });
      // §4 score upsert: on membership changes, persist the reflex's live scores
      // onto the ODP profile (the memory carrying the edge's numbers).
      const affPayload = update.data.affinity;
      if (consent.tracking && odpEnabled(this.env) && affPayload && membershipChanged) {
        void upsertOdpProfile(this.env, { visitorId: pipe.visitorId, sessionId: pipe.sessionId }, affPayload, journeyStage);
      }
    }

    // 8. Persist (single coalesced SQLite write, output-gated) + closed-form alarm.
    // CW31: with tracking off, nothing is written and the object forgets this
    // request; the answer above was computed, not kept.
    const sessionIdOut = this.pipeline.sessionId;
    if (before) {
      this.affinity = before.affinity;
      this.pipeline = before.pipeline;
    } else {
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
    }

    return {
      status: 200,
      body: {
        success: true,
        message: update
          ? 'Action processed and personalization updated'
          : 'Action processed, no personalization changes needed',
        ...(update ? { update } : {}),
        sessionId: sessionIdOut,
        cookiesUpdated: false, // identity is the stable visitor id — no session cookies on this host
        ...(odpReceipt ? { odp: odpReceipt } : {}),
        consent,
      },
      update,
    };
  }

  // ── The push envelope (same PersonalizationUpdate shape as the request path) ─

  private async buildUpdate(
    connectors: Connectors,
    now: number,
    source: string,
    reflex: ReflexResult | null,
    engagementScore: number
  ): Promise<PersonalizationUpdate> {
    const aff = this.affinity!;
    const pipe = this.pipeline!;
    const surface = this.surface();
    const cfg = await resolveReflexConfig(this.env, surface);
    const surfaceCatalog = await catalogFor(surface);
    const reflexOn = (this.env.REFLEX_ENABLED ?? 'true') !== 'false';

    const attributes: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...pipe.attributes };
    if (reflexOn) Object.assign(attributes, reflexAttributes(aff.reflex, now, cfg));

    const userAttributes = {
      segments: pipe.segments,
      ...attributes,
      engagement_score: engagementScore,
      session_count: pipe.sessionCount,
      journey_stage: pipe.journeyStage,
      days_since_first_seen: Math.floor((now - pipe.firstSeen) / (24 * 60 * 60 * 1000)),
      // No cookie-consent surface on this host (no PII either) — mirrors the
      // session path's defaults for a consenting shopper.
      tracking_consent: true,
      personalization_enabled: true,
    };

    const decisions = await connectors.decisions.decideAll(
      CATALOG_FLAG_KEYS,
      aff.shopperId,
      pipe.segments,
      userAttributes
    );
    const featureVariables: Record<string, any> = {};
    for (const [flagKey, decision] of Object.entries(decisions)) {
      featureVariables[flagKey] = decision.variables;
    }

    const anchorLine =
      typeof pipe.attributes.viewed_product_line === 'string'
        ? pipe.attributes.viewed_product_line
        : undefined;
    const recommendations = surfaceCatalog.getRecommendations({ line: anchorLine }, pipe.segments, 8);
    const sortOrder = surfaceCatalog
      .sortForSegments(null, pipe.segments, pipe.attributes)
      .slice(0, 24)
      .map((p) => p.id);

    return {
      type: 'personalization_update',
      userId: aff.shopperId,
      data: {
        segments: pipe.segments,
        decisions,
        featureVariables,
        recommendations,
        sortOrder,
        journeyStage: pipe.journeyStage,
        // Live affinity payload for the Affinity Instrument: dims (original catalog
        // value names) + memberships + this event's EXPLAIN records (§12 glass box)
        // + the ODP-confirmed subset — the exact shape the request path pushes.
        affinity: reflexOn
          ? {
              ...reflexSnapshot(aff.reflex, now, cfg),
              changed: reflex ? reflex.changes.explain : [],
              odpConfirmed: aff.odpSeed,
            }
          : undefined,
        sessionId: pipe.sessionId,
        engagementScore,
        timestamp: now,
        source,
      } as PersonalizationUpdate['data'],
    };
  }

  /** Push to every socket THIS object holds — never a cross-object hop. */
  private pushFrame(frame: unknown): void {
    const message = JSON.stringify(frame);
    for (const ws of this.state.getWebSockets()) {
      try {
        const p = (safeAttachment(ws) as { principal?: SessionCapability } | null)?.principal;
        if (!p || this.forwardTo) throw new SessionAccessError();
        assertSessionTarget(p, (frame as { userId?: string })?.userId);
        ws.send(message);
      } catch {
        try { ws.close(1008, 'Shopper session unavailable'); } catch { /* already closed */ }
        /* runtime reaps dead hibernated sockets */
      }
    }
  }

  // ── Closed-form alarm: exit-by-decay without polling + retention ────────────

  private retentionMs(): number {
    const days = Number(this.env.REFLEX_RETENTION_DAYS ?? DEFAULT_RETENTION_DAYS);
    return (Number.isFinite(days) && days > 0 ? days : DEFAULT_RETENTION_DAYS) * 24 * 60 * 60 * 1000;
  }

  private async scheduleNextCrossing(now: number): Promise<void> {
    if (!this.affinity) return;
    const at = computeNextAlarm(
      this.affinity.reflex,
      this.affinity.lastSeen,
      now,
      await resolveReflexConfig(this.env, this.surface()),
      this.retentionMs()
    );
    await this.state.storage.setAlarm(at);
  }

  async alarm(): Promise<void> {
    await this.serialize(async () => {
      await this.load();
      if (!this.affinity) return; // already erased
      const now = Date.now();
      const surface = this.surface();
      const cfg = await resolveReflexConfig(this.env, surface);

      // Retention (§12): idle past N days with no live sockets → self-expire.
      if (now - this.affinity.lastSeen >= this.retentionMs() && this.state.getWebSockets().length === 0) {
        await this.state.storage.deleteAll();
        this.affinity = null;
        this.pipeline = null;
        return;
      }

      // Lazy re-evaluation: tick() NEVER accumulates — decay is read-time math, so
      // the alarm never mutates scores; it only re-reads them at `now` and applies
      // the θ_out exits the closed form predicted.
      const res = tickReflex(this.affinity.reflex, now, cfg);
      this.affinity = { ...this.affinity, reflex: res.state, configVersion: cfg.version };

      const exited = res.changes.exited.length > 0 || res.changes.entered.length > 0;
      if (exited && this.pipeline) {
        await this.ensureSeeded(surface);
        const connectors = getConnectors(this.env);
        // Re-run the qualification tail with the decayed memberships — the union
        // shrinks, decisions revert, and the "they wandered off" push goes out.
        const ctxAttrs: Record<string, any> = { ...RETAIL_SIGNAL_DEFAULTS, ...this.pipeline.attributes };
        const qualCtx = {
          userId: this.affinity.shopperId,
          attributes: ctxAttrs,
          segments: this.pipeline.segments,
          surface,
        };
        const journeyStage = deriveStage(qualCtx);
        ctxAttrs.journey_stage = journeyStage;
        Object.assign(ctxAttrs, reflexAttributes(res.state, now, cfg));
        let localSegments: string[] = [];
        try {
          localSegments = await connectors.segments.fetchQualifiedSegments(this.affinity.shopperId, qualCtx);
        } catch (e) {
          console.error('ShopperReflex alarm qualification failed');
        }
        let odpSeed = this.affinity.odpSeed;
        let odpSeedAt = this.affinity.odpSeedAt;
        if (odpEnabled(this.env)) {
          ({ seed: odpSeed, seedAt: odpSeedAt } = await refreshOdpSeedIfDue(
            this.env,
            { visitorId: this.pipeline?.visitorId, sessionId: this.pipeline?.sessionId ?? '' },
            this.affinity.odpRecentEvents,
            { seed: odpSeed, seedAt: odpSeedAt },
            now,
            true // membership changed — instant read, same policy as the ingest path
          ));
          this.affinity = { ...this.affinity, odpSeed, odpSeedAt };
        }
        const prefix = audienceKeyPrefixFor(surface);
        const newSegments = Array.from(
          new Set([
            ...localSegments,
            ...(prefix ? res.state.audiences.map((k) => prefix + k) : res.state.audiences),
            ...odpSeed,
          ])
        );
        const changed =
          hasSegmentChanges(this.pipeline.segments, newSegments) ||
          this.pipeline.journeyStage !== journeyStage;
        this.pipeline = { ...this.pipeline, segments: newSegments, journeyStage };

        if (changed) {
          const engagementScore = calculateEngagementScore(this.pipeline.attributes);
          const update = await this.buildUpdate(connectors, now, 'reflex_alarm', res, engagementScore);
          this.pushFrame({ ...update, serverTimestamp: Date.now() });
        }
      }

      await this.state.storage.put({
        affinity: this.affinity,
        ...(this.pipeline ? { pipeline: this.pipeline } : {}),
      });
      await this.scheduleNextCrossing(now); // next exit, or the retention horizon
    });
  }

  // ── Snapshot door (same shape as GET /realtime/reflex) ─────────────────────

  private async handleSnapshot(): Promise<Response> {
    await this.load();
    const cfg = await resolveReflexConfig(this.env, this.surface());
    const now = Date.now();
    return json({
      ok: true,
      now,
      // Shape mirrors the session-path handler in src/routes/realtime.ts (the
      // client's honest drain animation reads these) — keep the two in sync.
      config: {
        tauMs: cfg.tauMs,
        K: cfg.K,
        thetaIn: cfg.thetaIn,
        thetaOut: cfg.thetaOut,
        dims: Object.fromEntries(
          cfg.dimensions
            .filter((d) => d.tauMs || d.K || d.thetaIn || d.thetaOut)
            .map((d) => [d.key, { tauMs: d.tauMs, K: d.K, thetaIn: d.thetaIn, thetaOut: d.thetaOut }])
        ),
      },
      affinity: this.affinity
        ? {
            ...reflexSnapshot(this.affinity.reflex, now, cfg),
            odpConfirmed: this.affinity.odpSeed ?? [],
          }
        : null,
      // CW29: the stage this object last derived, so the content decision can
      // put it on the cell without recomputing from counters it does not hold.
      journeyStage: this.pipeline?.journeyStage ?? null,
      // CW31: the switches the content decision and the outcome path honour.
      consent: await this.consentNow(),
      sessionId: this.pipeline?.sessionId ?? null,
    });
  }

  // ── Plumbing ────────────────────────────────────────────────────────────────

  /** Rehydrate the in-memory mirrors from ctx.storage (one read for both keys). */
  // ── CW31: consent ──────────────────────────────────────────────────────────

  /** The stored switches, or consenting when nothing was ever said. */
  private async consentNow(): Promise<{ tracking: boolean; personalization: boolean }> {
    if (this.consent === undefined) {
      const stored = (await this.state.storage.get('consent')) as { tracking?: unknown; personalization?: unknown } | undefined;
      this.consent = stored ? { tracking: stored.tracking !== false, personalization: stored.personalization !== false } : null;
    }
    return this.consent ?? { tracking: true, personalization: true };
  }

  /** Merge what the site said into the stored switches. Only an explicit boolean changes a switch. */
  private async setConsent(body: { tracking?: unknown; personalization?: unknown }): Promise<{ tracking: boolean; personalization: boolean }> {
    const current = await this.consentNow();
    const next = {
      tracking: typeof body.tracking === 'boolean' ? body.tracking : current.tracking,
      personalization: typeof body.personalization === 'boolean' ? body.personalization : current.personalization,
    };
    if (next.tracking !== current.tracking || next.personalization !== current.personalization || this.consent === null) {
      this.consent = next;
      await this.state.storage.put('consent', next);
    }
    return next;
  }

  // ── CW25: identity ─────────────────────────────────────────────────────────

  private async forwardTarget(): Promise<string | null> {
    if (this.forwardTo === undefined) {
      this.forwardTo = ((await this.state.storage.get('forwardTo')) as string | undefined) ?? null;
    }
    return this.forwardTo;
  }

  /** Called INSIDE the same serialized operation as the effect, never before it. */
  private async assertOwned(principal: SessionCapability, request?: Request): Promise<void> {
    assertSessionTarget(principal);
    if (await this.forwardTarget()) throw new SessionAccessError();
    await this.load();
    if ((this.affinity && this.affinity.shopperId !== principal.subject)
      || (this.pipeline?.visitorId && this.pipeline.visitorId !== principal.subject)
      || (this.pipeline && this.pipeline.sessionId !== principal.sessionId)
      || (principal.kind === 'recognized' && !this.affinity)) throw new SessionAccessError();
    // Cookies can restrict this owned object, never select a profile or enable consent.
    const hints = consentFromCookies(request?.headers.get('Cookie'));
    if (!hints.tracking || !hints.personalization) await this.setConsent({
      ...(!hints.tracking ? { tracking: false } : {}),
      ...(!hints.personalization ? { personalization: false } : {}),
    });
  }

  /**
   * When this object forwards, hand the request to the person's object by its
   * stored name. The name carries the brand prefix already, so no tenant needs
   * to be known here. A socket upgrade is NOT forwarded: the client is told the
   * id to reconnect under, and reconnects.
   */
  private async forwardIfLinked(request: Request): Promise<Response | null> {
    const to = await this.forwardTarget();
    if (!to) return null;
    const stub = this.env.SHOPPER_REFLEX.get(this.env.SHOPPER_REFLEX.idFromName(to));
    const res = await stub.fetch(request);
    const body = await res.text();
    const headers = new Headers(res.headers);
    headers.set('X-Forwarded-Shopper', to);
    return new Response(body, { status: res.status, headers });
  }

  /**
   * Fold another object's export into this one. The reflex vectors merge on the
   * decay invariant; counters add; first seen is the earliest. This object
   * becomes the person: its shopper id is the canonical one from here on.
   */
  private async handleAbsorb(request: Request): Promise<Response> {
    let body: { shopperId?: unknown; affinity?: AffinityRecord | null; pipeline?: PipelineRecord | null; now?: unknown } = {};
    try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
    if (typeof body.shopperId !== 'string' || body.shopperId === '') return json({ ok: false, error: 'shopperId required' }, 400);
    const shopperId = body.shopperId;
    const now = typeof body.now === 'number' ? body.now : Date.now();

    return this.serialize(async () => {
      await this.load();
      const cfg = await resolveReflexConfig(this.env, this.surface());
      const from = body.affinity ?? null;
      const fromPipe = body.pipeline ?? null;
      const merged = mergeReflexStates(this.affinity?.reflex, from?.reflex, now, cfg);

      this.affinity = {
        shopperId,
        reflex: merged.state,
        odpSeed: this.affinity?.odpSeed ?? from?.odpSeed ?? [],
        odpSeedAt: this.affinity?.odpSeedAt ?? from?.odpSeedAt ?? 0,
        odpRecentEvents: [...(from?.odpRecentEvents ?? []), ...(this.affinity?.odpRecentEvents ?? [])].slice(-10),
        lastSeen: Math.max(this.affinity?.lastSeen ?? 0, from?.lastSeen ?? 0) || now,
        configVersion: cfg.version,
      };
      const attributes: Record<string, any> = { ...(fromPipe?.attributes ?? {}), ...(this.pipeline?.attributes ?? {}) };
      for (const k of Object.keys(RETAIL_SIGNAL_DEFAULTS)) {
        const a = this.pipeline?.attributes?.[k]; const b = fromPipe?.attributes?.[k];
        if (typeof a === 'number' && typeof b === 'number') attributes[k] = a + b;
      }
      this.pipeline = {
        attributes,
        segments: [...new Set([...(this.pipeline?.segments ?? []), ...(fromPipe?.segments ?? []), ...merged.state.audiences])].sort(),
        journeyStage: this.pipeline?.journeyStage ?? fromPipe?.journeyStage ?? 'early',
        sessionId: this.pipeline?.sessionId ?? fromPipe?.sessionId ?? crypto.randomUUID(),
        visitorId: shopperId,
        firstSeen: Math.min(this.pipeline?.firstSeen ?? now, fromPipe?.firstSeen ?? now),
        sessionCount: (this.pipeline?.sessionCount ?? 0) + (fromPipe?.sessionCount ?? 0),
        surface: this.pipeline?.surface ?? fromPipe?.surface,
      };
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
      return json({ ok: true, shopperId, sessionId: this.pipeline.sessionId, audiences: merged.state.audiences, changes: merged.changes });
    });
  }

  /**
   * Apply historical rows, each at its own time, then evaluate at now. Touches
   * arrive already extracted by the route against the registry; this object
   * only does the arithmetic, and touches nothing about visits or lastSeen.
   */
  private async handleImport(request: Request): Promise<Response> {
    let body: { shopperId?: unknown; rows?: unknown; now?: unknown } = {};
    try { body = await request.json(); } catch { return json({ ok: false, error: 'invalid JSON body' }, 400); }
    const rows = Array.isArray(body.rows) ? body.rows as Array<{ action: string; at: number; touches: Array<{ dim: string; value: string }> }> : [];
    const now = typeof body.now === 'number' ? body.now : Date.now();
    return this.serialize(async () => {
      await this.load();
      const cfg = await resolveReflexConfig(this.env, this.surface());
      let state = this.affinity?.reflex ?? null;
      for (const r of rows) state = applyHistorical(state, { action: r.action, touches: r.touches }, r.at, cfg);
      const evaluated = tickReflex(state, now, cfg);
      const shopperId = typeof body.shopperId === 'string' && body.shopperId ? body.shopperId : (this.affinity?.shopperId ?? '');
      this.affinity = {
        shopperId,
        reflex: evaluated.state,
        odpSeed: this.affinity?.odpSeed ?? [],
        odpSeedAt: this.affinity?.odpSeedAt ?? 0,
        odpRecentEvents: this.affinity?.odpRecentEvents ?? [],
        lastSeen: this.affinity?.lastSeen ?? 0,
        configVersion: cfg.version,
      };
      if (!this.pipeline) {
        this.pipeline = {
          attributes: {}, segments: [...evaluated.state.audiences], journeyStage: 'early',
          sessionId: crypto.randomUUID(), visitorId: shopperId, firstSeen: now, sessionCount: 0,
        };
      } else {
        this.pipeline = { ...this.pipeline, segments: [...new Set([...this.pipeline.segments, ...evaluated.state.audiences])].sort() };
      }
      await this.state.storage.put({ affinity: this.affinity, pipeline: this.pipeline });
      await this.scheduleNextCrossing(now);
      return json({ ok: true, applied: rows.length, audiences: evaluated.state.audiences, changes: evaluated.changes });
    });
  }

  private async load(): Promise<void> {
    if (this.loaded) return;
    const stored = await this.state.storage.get(['affinity', 'pipeline']);
    this.affinity = (stored.get('affinity') as AffinityRecord | undefined) ?? null;
    this.pipeline = (stored.get('pipeline') as PipelineRecord | undefined) ?? null;
    this.loaded = true;
  }

  /** Same audiences the request path seeds (idempotent; version-gated to one KV read). */
  private async ensureSeeded(surface: DemoSurface = DEFAULT_SURFACE): Promise<void> {
    if (this.seeded.has(surface)) return;
    try {
      await ensureAudiencesSeeded(this.env, await catalogFor(surface), surface);
      this.seeded.add(surface);
    } catch (error) {
      console.error('ShopperReflex: audience seeding failed');
    }
  }

  /** The surface this shopper object belongs to (persisted; absent ⇒ coach). */
  private surface(): DemoSurface {
    return this.pipeline?.surface ?? DEFAULT_SURFACE;
  }

  private allowIngest(now: number): boolean {
    const limitRaw = Number(this.env.REFLEX_RATE_LIMIT_PER_MIN ?? DEFAULT_RATE_LIMIT_PER_MIN);
    const limit = Number.isFinite(limitRaw) && limitRaw > 0 ? limitRaw : DEFAULT_RATE_LIMIT_PER_MIN;
    if (now - this.rate.windowStart >= 60_000) {
      this.rate = { windowStart: now, count: 0 };
    }
    this.rate.count++;
    return this.rate.count <= limit;
  }

  private serialize<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.chain.then(fn, fn);
    this.chain = run.then(
      () => undefined,
      () => undefined
    );
    return run;
  }
}

function safeAttachment(ws: WebSocket): unknown {
  try {
    return ws.deserializeAttachment();
  } catch {
    return null;
  }
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

// src/sdk/core.ts
// The shared core: identity, the event bus, and transport. Non-negotiable as a
// shared piece because events and decisions must be keyed to the same visitor
// id and one socket serves both directions. Extracted from the demo storefront:
// the socket URL, the welcome frame, the reconnect delay, the action envelope
// and the POST-versus-push dedupe are its behavior, verbatim.

import { currentSessionId, DEFAULT_VISITOR_KEY, entrySignals, writeVisitorId, rotateBrowsingSession } from './identity';
import { toWire } from './wire';
import type {
  ActionEnvelope, ClientConfig, CoreEvents, DecisionSet, EngineUpdate, EntrySignals, Host, Paths,
  SdkEventType, SocketLike, SocketStatus,
} from './types';

export const DEFAULT_PATHS: Paths = {
  identitySession: '/v1/{tenant}/identity/session',
  action: '/realtime/action',
  ws: '/realtime/ws',
  reflex: '/realtime/reflex',
  snapshot: '/v1/{tenant}/decisions/snapshot',
  identityLink: '/v1/{tenant}/identity/link',
  identityDetach: '/v1/{tenant}/identity/detach',
};

export interface ResolvedConfig {
  tenant: string;
  brand?: string;
  endpoint: string;
  sdkKey?: string;
  source: string;
  surface?: string;
  listenOnly: boolean;
  heartbeatMs: number;
  reconnectMs: number;
  hydrateTimeoutMs: number;
  visitorIdKey: string;
  paths: Paths;
}

export function resolveConfig(c: ClientConfig, host: Host): ResolvedConfig {
  const origin = host.location ? `${host.location.protocol}//${host.location.host}` : '';
  return {
    tenant: c.tenant,
    ...(c.brand ? { brand: c.brand } : {}),
    endpoint: (c.endpoint ?? origin).replace(/\/+$/, ''),
    ...(c.sdkKey ? { sdkKey: c.sdkKey } : {}),
    source: c.source ?? 'sdk',
    ...(c.surface ? { surface: c.surface } : {}),
    listenOnly: Boolean(c.listenOnly),
    heartbeatMs: c.heartbeatMs ?? 25_000,
    reconnectMs: c.reconnectMs ?? 3_000,
    hydrateTimeoutMs: c.hydrateTimeoutMs ?? 1_500,
    visitorIdKey: c.visitorIdKey ?? DEFAULT_VISITOR_KEY,
    paths: { ...DEFAULT_PATHS, ...(c.paths ?? {}) },
  };
}

export interface SendOptions {
  /** Fire-and-forget through the beacon API, for page-hide moments. */
  beacon?: boolean;
  keepalive?: boolean;
}

export interface Core {
  readonly generation: number;
  ready(transition?: boolean): Promise<boolean>;
  beginTransition(): number;
  finishTransition(generation: number): void;
  forgetSession(generation: number): void;
  isCurrent(generation: number): boolean;
  adoptSession(session: unknown, generation: number, reason: 'identified' | 'logout'): boolean;
  readonly config: ResolvedConfig;
  readonly host: Host;
  readonly visitorId: string;
  readonly anonId: string;
  readonly sessionId: string;
  readonly profileSessionId: string;
  readonly entry: EntrySignals;
  readonly socketStatus: SocketStatus;
  on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void;
  emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void;
  /** The envelope POST /realtime/action validates, for this event. Pure. */
  envelope(type: SdkEventType, data?: Record<string, unknown>): ActionEnvelope;
  send(type: SdkEventType, data?: Record<string, unknown>, opts?: SendOptions): Promise<EngineUpdate | null>;
  url(path: string, query?: Record<string, string | undefined>): string;
  headers(extra?: Record<string, string>): Record<string, string>;
  getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null>;
  /** POST JSON with the site key and credentials; never throws. */
  postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }>;
  /** CW25: the browser now carries this id. Writes both stores, announces the change, reconnects the socket if it was open. */
  setVisitorId(id: string, reason: 'identified' | 'logout'): void;
  connect(): void;
  disconnect(): void;
  /** Apply an engine update from either door, once. */
  applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void;
}

export function createCore(config: ClientConfig, host: Host): Core {
  const cfg = resolveConfig(config, host);
  let visitorId = '', sessionId = '', anonId = '';
  let generation = 0;
  let transitioning = false;
  let capability = '';
  let expiresAt = 0;
  let bootstrapping: Promise<boolean> | null = null;
  const capabilityKey = `opt_shopper_session:${encodeURIComponent(cfg.endpoint)}:${encodeURIComponent(cfg.tenant)}`;
  const session = () => currentSessionId(host);
  const entry = entrySignals(host);

  const listeners = new Map<string, Set<(...args: unknown[]) => void>>();
  function on<K extends keyof CoreEvents>(event: K, fn: CoreEvents[K]): () => void {
    const set = listeners.get(event) ?? new Set();
    set.add(fn as (...args: unknown[]) => void);
    listeners.set(event, set);
    return () => { set.delete(fn as (...args: unknown[]) => void); };
  }
  function emit<K extends keyof CoreEvents>(event: K, ...args: Parameters<CoreEvents[K]>): void {
    const g = generation;
    for (const fn of listeners.get(event) ?? []) { if (generation !== g) break; try { fn(...args); } catch { /* a listener must never break the page */ } }
  }

  // A shopper's own action returns the update in the POST response AND echoes
  // it over the socket. Apply once: both carry the same server timestamp.
  let lastAppliedTs: number | undefined;
  function applyIncoming(update: EngineUpdate, fromPush: boolean, rttMs: number | null): void {
    if (typeof update.timestamp === 'number') {
      if (fromPush && update.timestamp === lastAppliedTs) return;
      lastAppliedTs = update.timestamp;
    }
    emit('update', update, { fromPush, rttMs });
  }

  function url(path: string, query?: Record<string, string | undefined>): string {
    const base = `${cfg.endpoint}${path.replace('{tenant}', encodeURIComponent(cfg.tenant))}`;
    const parts = Object.entries(query ?? {}).filter(([, v]) => v !== undefined && v !== '')
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`);
    return parts.length ? `${base}?${parts.join('&')}` : base;
  }
  function headers(extra: Record<string, string> = {}): Record<string, string> {
    return { ...(cfg.sdkKey ? { 'X-SDK-Key': cfg.sdkKey } : {}), 'X-Tenant': cfg.tenant, ...(capability ? { 'X-Shopper-Session': capability } : {}), ...extra };
  }

  function isCurrent(g: number): boolean { return g === generation && !!capability && expiresAt * 1000 > host.now(); }
  function beginTransition(): number {
    const g = ++generation;
    transitioning = true;
    bootstrapping = null;
    lastAppliedTs = undefined;
    const reconnect = wanted;
    disconnect();
    if (g !== generation) return g;
    wanted = reconnect;
    emit('generation', g);
    return g;
  }
  function finishTransition(g: number): void {
    if (g !== generation) return;
    transitioning = false;
    if (wanted) connect();
  }
  function forgetSession(g: number): void {
    if (g !== generation) return;
    capability = ''; expiresAt = 0; visitorId = ''; sessionId = ''; anonId = '';
    try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
    writeVisitorId(host, cfg.visitorIdKey, '');
    rotateBrowsingSession(host);
  }
  function adoptSession(value: unknown, g: number, reason: 'identified' | 'logout'): boolean {
    const v = value as { tenant?: unknown; subject?: unknown; sessionId?: unknown; capability?: unknown; kind?: unknown; exp?: unknown; iat?: unknown } | null;
    if (g !== generation || !v || v.tenant !== cfg.tenant || typeof v.subject !== 'string' || !v.subject
      || typeof v.sessionId !== 'string' || !v.sessionId || typeof v.capability !== 'string' || !/^ss1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(v.capability)
      || (v.kind !== 'anonymous' && v.kind !== 'recognized') || typeof v.exp !== 'number' || !Number.isSafeInteger(v.exp)
      || typeof v.iat !== 'number' || !Number.isSafeInteger(v.iat) || v.iat > host.now() / 1000 || v.exp * 1000 <= host.now() || v.exp - v.iat > 86400 || v.exp <= v.iat) return false;
    const previous = visitorId;
    if (previous && previous !== v.subject) rotateBrowsingSession(host);
    visitorId = v.subject; sessionId = v.sessionId; capability = v.capability; expiresAt = v.exp;
    anonId = v.kind === 'anonymous' ? v.subject : '';
    try { host.storage.set(capabilityKey, capability); } catch { /* storage unavailable */ }
    writeVisitorId(host, cfg.visitorIdKey, visitorId);
    emit('identity', { visitorId, previous, reason });
    if (g !== generation) return false;
    if (wanted && !transitioning) connect();
    return true;
  }
  function ready(transition = false): Promise<boolean> {
    if (transitioning && !transition) return Promise.resolve(false);
    if (isCurrent(generation)) return Promise.resolve(true);
    if (bootstrapping) return bootstrapping;
    if (capability) {
      const g = beginTransition();
      if (g !== generation) return Promise.resolve(false);
      transitioning = false; capability = ''; expiresAt = 0; visitorId = ''; sessionId = '';
    }
    const g = generation;
    let persisted = '';
    try { persisted = host.storage.get(capabilityKey) ?? ''; } catch { /* storage unavailable */ }
    const operation = (async () => {
      try {
        const request = () => host.fetch(url(cfg.paths.identitySession), { method: 'POST', credentials: 'include', headers: { ...headers({ 'Content-Type': 'application/json' }), ...(persisted ? { 'X-Shopper-Session': persisted } : {}) }, body: '{}' });
        let res = await request();
        if (res.status === 401 && persisted && g === generation) {
          persisted = '';
          try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
          res = await request();
        }
        const body = await res.json() as { ok?: unknown; session?: unknown } | null;
        if (g !== generation) return false;
        if (!res.ok || body?.ok !== true) {
          if (res.status === 401) try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
          return false;
        }
        return adoptSession(body.session, g, 'logout');
      } catch { return false; }
    })();
    bootstrapping = operation;
    void operation.finally(() => { if (bootstrapping === operation) bootstrapping = null; });
    return operation;
  }

  function envelope(type: SdkEventType, data: Record<string, unknown> = {}): ActionEnvelope {
    const w = toWire(type, data);
    return {
      type: w.type,
      userId: visitorId,
      anonymousId: anonId,
      sessionId,
      browsingSessionId: session(),
      data: w.data,
      source: cfg.source,
      ...(cfg.surface ? { surface: cfg.surface } : {}),
      entry,
      timestamp: host.now(),
    };
  }

  async function send(type: SdkEventType, data: Record<string, unknown> = {}, opts: SendOptions = {}): Promise<EngineUpdate | null> {
    const pending = ready();
    const g = generation;
    if (!await pending || !isCurrent(g)) return null;
    const env = envelope(type, data);
    const body = JSON.stringify(env);
    const target = url(cfg.paths.action);
    const t0 = host.now();
    try {
      const res = await host.fetch(target, {
        method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body,
        ...(opts.keepalive || opts.beacon ? { keepalive: true } : {}),
      });
      const json = (await res.json()) as { update?: { data?: EngineUpdate }; odp?: unknown } | null;
      if (!res.ok || !isCurrent(g)) return null;
      emit('sent', env, { via: 'fetch' });
      if (!isCurrent(g)) return null;
      if (json?.odp) emit('receipt', json.odp, { via: 'fetch' });
      if (!isCurrent(g)) return null;
      const update = json?.update?.data ?? null;
      if (update) applyIncoming(update, false, host.now() - t0);
      return isCurrent(g) ? update : null;
    } catch {
      return null;
    }
  }

  async function getJson(path: string, query?: Record<string, string | undefined>): Promise<unknown | null> {
    const pending = ready();
    const g = generation;
    if (!await pending || !isCurrent(g)) return null;
    try {
      const res = await host.fetch(url(path, query), { method: 'GET', headers: headers(), credentials: 'include' });
      const json = await res.json();
      return res.ok && isCurrent(g) ? json : null;
    } catch {
      return null;
    }
  }

  async function postJson(path: string, body: unknown): Promise<{ ok: boolean; status: number; json: unknown }> {
    const g = generation;
    const identityRequest = path === cfg.paths.identityLink || path === cfg.paths.identityDetach;
    if (!await ready(identityRequest) || !isCurrent(g)) return { ok: false, status: 0, json: null };
    try {
      const res = await host.fetch(url(path), { method: 'POST', headers: headers({ 'Content-Type': 'application/json' }), credentials: 'include', body: JSON.stringify(body) });
      let json: unknown = null;
      try { json = await res.json(); } catch { json = null; }
      return isCurrent(g) ? { ok: res.ok, status: res.status, json } : { ok: false, status: 0, json: null };
    } catch {
      return { ok: false, status: 0, json: null };
    }
  }

  function setVisitorId(id: string, reason: 'identified' | 'logout'): void {
    const previous = visitorId;
    if (!id) return;
    const g = beginTransition();
    if (g !== generation) return;
    capability = ''; expiresAt = 0; sessionId = ''; anonId = '';
    rotateBrowsingSession(host);
    try { host.storage.set(capabilityKey, ''); } catch { /* storage unavailable */ }
    visitorId = id;
    writeVisitorId(host, cfg.visitorIdKey, id);
    emit('identity', { visitorId: id, previous, reason });
    finishTransition(g);
    // Pushes go to the object named by the id: a socket still open under the old one hears nothing.
    if (wanted) connect();
  }

  // ── The socket ──────────────────────────────────────────────────────────────
  let socket: SocketLike | null = null;
  let status: SocketStatus = host.openSocket ? 'closed' : 'unavailable';
  let wanted = false;
  let heartbeat: unknown = null;
  let reconnectTimer: unknown = null;
  let socketGeneration = 0;

  function setStatus(s: SocketStatus): void { status = s; emit('socket', s); }

  function socketUrl(): string | null {
    if (!cfg.endpoint) return null;
    const base = cfg.endpoint.replace(/^http(s?):/, (_m, secure: string) => `ws${secure}:`);
    const q = new URLSearchParams({ userId: visitorId, sessionId, tenant: cfg.tenant, ...(cfg.sdkKey ? { sdkKey: cfg.sdkKey } : {}) });
    return `${base}${cfg.paths.ws}?${q.toString()}`;
  }

  function handleFrame(raw: unknown): void {
    const g = generation;
    let msg: { type?: string; data?: Record<string, unknown>; [k: string]: unknown };
    try { msg = typeof raw === 'string' ? JSON.parse(raw) : (raw as typeof msg); } catch { return; }
    if (!msg || typeof msg !== 'object') return;
    const data = (msg.data ?? {}) as Record<string, unknown>;
    switch (msg.type) {
      case 'connected': setStatus('connected'); return;
      case 'heartbeat_response': return;
      case 'odp_receipt': emit('receipt', data, { via: 'push' }); return;
      case 'content_decisions': emit('decisions', msg as unknown as DecisionSet); return;
      default: break;
    }
    if (msg.type === 'audience_published' || data.audienceWentLive) emit('audience', data.audienceWentLive ?? msg.audienceWentLive ?? data);
    if (!isCurrent(g)) return;
    if (msg.type === 'personalization_update' || msg.type === 'segment_update' || data.segments) {
      const ms = typeof data.decisionMs === 'number' ? data.decisionMs : null;
      applyIncoming(data as EngineUpdate, true, ms);
    }
  }

  function stopHeartbeat(): void { if (heartbeat !== null) { host.clearInterval(heartbeat); heartbeat = null; } }

  function connect(): void {
    wanted = true;
    const g = generation, sg = ++socketGeneration;
    void ready().then(ok => {
      if (ok && wanted && isCurrent(g) && sg === socketGeneration) openSocket(g, sg);
    });
  }
  function openSocket(g: number, sg: number): void {
    if (!host.openSocket) { setStatus('unavailable'); return; }
    const target = socketUrl();
    if (!target) { setStatus('unavailable'); return; }
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    setStatus('connecting');
    if (g !== generation || sg !== socketGeneration || !wanted || transitioning) return;
    try { socket = host.openSocket(target, ['shopper-session-v1', capability]); } catch { setStatus('error'); return; }
    const s = socket;
    const current = () => sg === socketGeneration && isCurrent(g);
    s.onopen = () => {
      if (!current()) { s.close(); return; }
      setStatus('connected');
      stopHeartbeat();
      heartbeat = host.setInterval(() => {
        if (!current()) { s.close(); return; }
        if (s.readyState === 1) { try { s.send(JSON.stringify({ type: 'heartbeat' })); } catch { /* dying socket */ } }
      }, cfg.heartbeatMs);
    };
    s.onmessage = (ev) => { if (current()) handleFrame(ev.data); };
    s.onerror = () => { if (current()) setStatus('error'); };
    s.onclose = () => {
      if (!current()) return;
      stopHeartbeat();
      if (!wanted) { setStatus('closed'); return; }
      setStatus('reconnecting');
      reconnectTimer = host.setTimeout(() => { reconnectTimer = null; if (wanted) connect(); }, cfg.reconnectMs);
    };
  }

  function disconnect(): void {
    socketGeneration++;
    wanted = false;
    stopHeartbeat();
    if (reconnectTimer !== null) { host.clearTimeout(reconnectTimer); reconnectTimer = null; }
    try { socket?.close(); } catch { /* ignore */ }
    socket = null;
    setStatus('closed');
  }

  return {
    config: cfg, host, entry,
    get anonId() { return anonId; },
    get generation() { return generation; },
    ready, beginTransition, finishTransition, forgetSession, isCurrent, adoptSession,
    get visitorId() { return visitorId; },
    get sessionId() { return session(); },
    get profileSessionId() { return sessionId; },
    get socketStatus() { return status; },
    on, emit, envelope, send, url, headers, getJson, postJson, setVisitorId, connect, disconnect, applyIncoming,
  };
}

// src/sdk/identify.ts
// CW25, the client half of identity stitching (docs/architecture/25-identity-stitching.md §4).
// identify() tells the edge which account this browser belongs to; on success the
// browser carries the person's shopper id as its visitor id from then on, and the
// socket reconnects under it, because pushes go to the object named by the id.
// logout() detaches, mints a fresh anonymous id, and reconnects under that. The
// assertion is always computed by the site's backend and handed to the page.
// A proof provider can obtain a fresh visitor-bound assertion after a 409 and
// successful detach; static proof is never reused for a different visitor.

import type { Core } from './core';

export interface IdentifyOptions {
  /** HMAC from the site's backend over tenant, visitorId, accountId and exp (see signAssertion). */
  assertion?: string;
  /** Unix seconds the assertion expires, at most 24 h ahead. */
  exp?: number;
  /** Obtain backend proof for this exact request. Called again after a successful 409 detach. */
  getAssertion?: (claim: { tenant: string; visitorId: string; accountId: string }) =>
    { assertion: string; exp: number } | Promise<{ assertion: string; exp: number }>;
  /** Where the sign-in happened, for the audit trail: 'login', 'checkout', … */
  source?: string;
}

export type IdentifyResult =
  | { ok: true; shopperId: string; visitorId: string; outcome: string | null; retried: boolean }
  | { ok: false; status: number; error: string; retried: boolean };

export interface LogoutResult { ok: boolean; status: number; visitorId: string }

export interface Identity {
  identify(accountId: string, options?: IdentifyOptions): Promise<IdentifyResult>;
  logout(): Promise<LogoutResult>;
}

export function createIdentity(core: Core): Identity {
  const failure = (error: string, status = 0, retried = false): IdentifyResult => ({ ok: false, status, error, retried });
  async function attempt(accountId: string, o: IdentifyOptions, generation: number, retry = false): Promise<
    { visitorId: string; response: Awaited<ReturnType<Core['postJson']>> } | { failure: IdentifyResult }
  > {
    const visitorId = core.visitorId;
    let assertion = o.assertion, exp = o.exp;
    if (o.getAssertion !== undefined) {
      try {
        if (typeof o.getAssertion !== 'function') return { failure: failure('identity proof provider invalid') };
        const proof = await o.getAssertion({ tenant: core.config.tenant, visitorId, accountId });
        if (!core.isCurrent(generation) || core.visitorId !== visitorId) return { failure: failure('identity changed during identify') };
        assertion = proof?.assertion; exp = proof?.exp;
        if (typeof assertion !== 'string' || !assertion.trim() || assertion.length > 200 || !Number.isInteger(exp)) {
          return { failure: failure('identity proof provider returned invalid proof') };
        }
      } catch {
        return { failure: failure('identity proof provider failed') };
      }
    }
    if (!core.isCurrent(generation) || core.visitorId !== visitorId) return { failure: failure('identity changed during identify') };
    const response = await core.postJson(core.config.paths.identityLink, {
      visitorId, accountId,
      ...(o.source ? { source: o.source } : {}),
      ...(typeof exp === 'number' ? { exp } : {}),
      ...(assertion ? { assertion } : {}),
    });
    if (!core.isCurrent(generation) || core.visitorId !== visitorId) return { failure: failure('identity changed during identify', 0, retry) };
    return { visitorId, response };
  }

  async function logout(): Promise<LogoutResult> {
    const g = core.beginTransition();
    try {
      if (!await core.ready(true) || !core.isCurrent(g)) { core.forgetSession(g); return { ok: false, status: 0, visitorId: core.visitorId }; }
      const res = await core.postJson(core.config.paths.identityDetach, { visitorId: core.visitorId });
      const body = res.json as { ok?: unknown; detached?: unknown; session?: unknown } | null;
      const ok = core.isCurrent(g) && res.ok && body?.ok === true && body.detached === true && core.adoptSession(body.session, g, 'logout');
      if (!ok) core.forgetSession(g);
      return { ok, status: res.status, visitorId: core.visitorId };
    } finally { core.finishTransition(g); }
  }

  async function identify(accountId: string, options: IdentifyOptions = {}): Promise<IdentifyResult> {
    if (!accountId || typeof accountId !== 'string') return { ok: false, status: 0, error: 'accountId required', retried: false };
    const g = core.beginTransition();
    try {
    if (!await core.ready(true) || !core.isCurrent(g)) return failure('shopper session unavailable');
    let retried = false;
    let attempted = await attempt(accountId, options, g);
    if ('failure' in attempted) return attempted.failure;
    if (!core.isCurrent(g) || core.visitorId !== attempted.visitorId) return failure('identity changed during identify');
    if (attempted.response.status === 409 && options.getAssertion !== undefined) {
      // A retry needs successful detach AND proof for the freshly minted id.
      const detached = await core.postJson(core.config.paths.identityDetach, { visitorId: attempted.visitorId });
      if (!core.isCurrent(g) || core.visitorId !== attempted.visitorId) return failure('identity changed during identify');
      const body = detached.json as { ok?: unknown; detached?: unknown; session?: unknown } | null;
      if (!detached.ok || body?.ok !== true || body?.detached !== true) return failure('identity detach failed', detached.status);
      if (!core.adoptSession(body.session, g, 'logout')) return failure('identity detach failed', detached.status);
      attempted = await attempt(accountId, options, g, true);
      if ('failure' in attempted) return attempted.failure;
      retried = true;
    }
    if (!core.isCurrent(g) || core.visitorId !== attempted.visitorId) return failure('identity changed during identify', 0, retried);
    const res = attempted.response;
    const body = (res.json ?? {}) as { ok?: boolean; carry?: unknown; shopperId?: unknown; outcome?: unknown; error?: unknown; session?: { subject?: unknown; kind?: unknown } };
    const shopperId = typeof body.carry === 'string' ? body.carry : typeof body.shopperId === 'string' ? body.shopperId : null;
    if (!res.ok || body.ok === false || !shopperId) {
      return { ok: false, status: res.status, error: typeof body.error === 'string' ? body.error : 'link refused', retried };
    }
    if (body.session?.kind !== 'recognized' || body.session.subject !== shopperId || !core.adoptSession(body.session, g, 'identified')) return failure('shopper session unavailable', res.status, retried);
    return { ok: true, shopperId, visitorId: core.visitorId, outcome: typeof body.outcome === 'string' ? body.outcome : null, retried };
    } finally { core.finishTransition(g); }
  }

  return { identify, logout };
}

// src/routes/identity.test.ts
//
// CW25 through the wire, on the session host: a phone and a laptop browse as
// strangers, both sign in to the same account, and the person is the sum. Then
// the rules around the edges: the assertion, the shopper-id refusal, the shared
// computer, detach, history in both formats, and who may ask what.

import { describe, it, expect, beforeEach, vi } from 'vitest';
import * as jose from 'jose';
import type { Env } from '@/types/env';
import { identityRoutes } from '@/routes/identity';
import { SessionManager } from '@/services/SessionManager';
import { DEFAULT_REFLEX_CONFIG, apply, audienceKey, emptyState, snapshot, type ReflexState } from '@/reflex/core';
import { signAssertion } from '@/identity/assertion';
import { shopperIdFor } from '@/identity/shopperId';
import { createCore } from '@/sdk/core';
import { createIdentity } from '@/sdk/identify';
import { memoryHost } from '@/sdk/memoryHost';
import { issueSessionCapability, SHOPPER_HEADER } from '@/identity/sessionCapability';

class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string) { const r = this.store.get(key); return r === undefined ? null : (type === 'json' ? JSON.parse(r) : r); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

const cfg = DEFAULT_REFLEX_CONFIG;
const TABBY = audienceKey('line', 'Tabby');

/** Enough of R2 for the ledger's tombstones: put, get, delete, list by prefix. */
class FakeR2 {
  store = new Map<string, string>();
  async put(key: string, body: string) { this.store.set(key, body); }
  async get(key: string) { const v = this.store.get(key); return v === undefined ? null : { text: async () => v }; }
  async delete(key: string) { this.store.delete(key); }
  async list(o: { prefix: string }) { return { objects: [...this.store.keys()].filter((k) => k.startsWith(o.prefix)).map((key) => ({ key })), truncated: false }; }
}

const mkEnv = (over: Record<string, unknown> = {}): Env => ({
  CACHE: new FakeKV(), SESSIONS: new FakeKV(), STORAGE: new FakeR2(), ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock',
  JWT_SECRET: 'w0202-synthetic-route-signing-material', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a', IDENTITY_SECRETS: 'coach:s3cret', ...over,
} as unknown as Env);
const token = () => new jose.SignJWT({ sub: 'ops' }).setProtectedHeader({ alg: 'HS256' }).setIssuedAt().setIssuer('i').setAudience('a').setExpirationTime('5m').sign(new TextEncoder().encode('w0202-synthetic-route-signing-material'));

const browse = (values: string[], at: number): ReflexState => {
  let s = emptyState(cfg);
  values.forEach((v, i) => { s = apply(s, { action: 'product_view', touches: [{ dim: 'line', value: v }] }, at + i * 1000, cfg).state; });
  return s;
};

let env: Env;
let auth: Record<string, string>;
let ownedIds = new Map<string, string>();

async function seedDevice(visitorId: string, sessionId: string, values: string[]) {
  ownedIds.set(visitorId, sessionId);
  const sm = new SessionManager(env);
  // Built a few seconds ago, not at T0: the route merges at Date.now(), and a vector from 2023 is dust by now.
  await sm.createOrUpdateSession(sessionId, visitorId, { reflex: browse(values, Date.now() - 5_000), attributes: { product_views: values.length } });
}

async function call(path: string, init: RequestInit & { json?: unknown } = {}) {
  const headers: Record<string, string> = { ...(init.headers as Record<string, string> ?? {}) };
  let body = init.body;
  if (init.json !== undefined) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(init.json); }
  const res = await identityRoutes.request(path, { ...init, headers, body }, env);
  return { status: res.status, body: (await res.json()) as Record<string, any>, headers: res.headers };
}

async function ownedCall(path: string, init: RequestInit & { json?: unknown }) {
  const visitorId = (init.json as { visitorId?: string })?.visitorId ?? 'vis-00000000-0000-4000-8000-000000000099';
  const subject = /^[A-Za-z0-9_.-]+$/.test(visitorId) ? visitorId : 'vis-00000000-0000-4000-8000-000000000099';
  const session = await issueSessionCapability(env, { tenant: 'coach', subject, sessionId: ownedIds.get(subject) ?? 's-owned-fresh', kind: subject.startsWith('sh_') ? 'recognized' : 'anonymous' });
  return call(path, { ...init, headers: { ...init.headers, [SHOPPER_HEADER]: session.capability } });
}

// Explicit positive-fixture signing only. The SDK transport below never uses this helper.
async function signedCall(path: string, init: RequestInit & { json?: unknown }) {
  const body = init.json as { visitorId: string; accountId: string };
  const exp = Math.floor(Date.now() / 1000) + 120;
  const assertion = await signAssertion('s3cret', 'coach', body.visitorId, body.accountId, exp);
  return ownedCall(path, { ...init, json: { ...body, exp, assertion } });
}

beforeEach(async () => {
  env = mkEnv();
  ownedIds = new Map();
  auth = { Authorization: `Bearer ${await token()}` };
});

describe('the link, on the session host', () => {
  it('a phone signs in: the response names the person, sets the cookie, and the old cookie reads the person', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby', 'Tabby']);
    const r = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    expect(r.status).toBe(200);
    expect(r.body.outcome).toBe('linked');
    expect(r.body.assurance).toBe('signed');
    expect(r.body.shopperId).toBe(await shopperIdFor(env, 'coach', 'acct-1001'));
    expect(r.body.carry).toBe(r.body.shopperId);
    expect(r.body.audiences).toContain(TABBY);
    const cookies = r.headers.get('set-cookie') ?? '';
    expect(cookies).toContain('opt_session_id=');
    expect(cookies).toContain(`opt_user_id=${r.body.shopperId}`);
    expect(cookies).not.toContain('opt_session_id=s-phone');

    const sm = new SessionManager(env);
    expect((await sm.getSession('s-phone'))?.userId).toBe(r.body.shopperId);
  });

  it('a laptop signs in to the same account: cross-device, the person is the sum', async () => {
    await seedDevice('vis-00000000-0000-4000-8000-000000000001', 's-phone', ['Tabby', 'Tabby']);
    await seedDevice('vis-00000000-0000-4000-8000-000000000002', 's-laptop', ['Rogue', 'Rogue', 'Tabby']);
    const a = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000001', accountId: 'acct-1001' } });
    const b = await signedCall('/coach/identity/link', { method: 'POST', json: { visitorId: 'vis-00000000-0000-4000-8000-000000000002', accountId: 'acct-1001', source: 'checkout' } });
    expect(b.body.shopperId).toBe(a.body.shopperId);
    expect(b.body.outcome).toBe('linked');

    const sm = new SessionManager(env);
    const person = await sm.getSessionByUserId(b.body.shopperId);
    const snap = snapshot(person!.reflex!, Date.now(), cfg);
    expect(Object.keys(snap.dims.line).sort()).toEqual(['Rogue', 'Tabby']);
    expect(person!.attributes.product_views).toBe(5);
    expect(person!.metadata.visitCount).toBe(2);
    // Either browser resolves to the person.
