  }
  async delete(k: string) { return this.map.delete(k); }
  async deleteAll() { this.map.clear(); }
  async setAlarm() { /* not exercised here */ }
  async getAlarm() { return null; }
}
class FakeKV {
  store = new Map<string, string>();
  async get(key: string, type?: string): Promise<any> { const v = this.store.get(key); return v === undefined ? null : (type === 'json' ? JSON.parse(v) : v); }
  async put(key: string, value: string) { this.store.set(key, value); }
  async delete(key: string) { this.store.delete(key); }
  async list(o?: { prefix?: string }) { const p = o?.prefix ?? ''; return { keys: [...this.store.keys()].filter((k) => k.startsWith(p)).map((name) => ({ name })) }; }
}

let storage: FakeStorage;
let shopper: ShopperReflex;

beforeEach(() => {
  vi.useFakeTimers(); vi.setSystemTime(t0);
  storage = new FakeStorage();
  const state = { storage, acceptWebSocket: () => undefined, getWebSockets: () => [] } as unknown as DurableObjectState;
  const env = { CACHE: new FakeKV(), SESSIONS: new FakeKV(), ENVIRONMENT: 'test', CONNECTOR_MODE: 'mock' } as unknown as Env;
  shopper = new ShopperReflex(state, env);
});
afterEach(() => { vi.useRealTimers(); });

const post = async (path: string, body: unknown) => {
  const res = await shopper.fetch(new Request(`https://do${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }));
  return { status: res.status, body: (await res.json()) as any };
};
const get = async (path: string) => { const res = await shopper.fetch(new Request(`https://do${path}`)); return (await res.json()) as any; };
const view = (extra: Record<string, unknown> = {}) => ({ type: 'product_view', userId: 'vis-c', data: { productId: TABBY_ID, action: 'product_view', ...extra }, source: 'test' });

describe('the switches', () => {
  it('are consenting when nothing was ever said, on the snapshot and the envelope', async () => {
    expect((await get('/snapshot')).consent).toEqual({ tracking: true, personalization: true });
    const r = await post('/ingest', view());
    expect(r.body.consent).toEqual({ tracking: true, personalization: true });
    expect(storage.map.has('affinity')).toBe(true);
  });

  it('are set through the door, only by an explicit boolean, and remembered', async () => {
    const r = await post('/consent', { personalization: false, tracking: 'no' as never });
    expect(r.body.consent).toEqual({ tracking: true, personalization: false });
    expect(storage.map.get('consent')).toEqual({ tracking: true, personalization: false });
    expect((await get('/snapshot')).consent).toEqual({ tracking: true, personalization: false });
  });

  it('can arrive on an event, under data.consent', async () => {
    const r = await post('/ingest', view({ consent: { tracking: false } }));
    expect(r.body.consent).toEqual({ tracking: false, personalization: true });
    expect(storage.map.get('consent')).toEqual({ tracking: false, personalization: true });
  });
});

describe('tracking off', () => {
  it('answers the request but keeps nothing: no affinity written, the object unchanged', async () => {
    await post('/consent', { tracking: false });
    const putsBefore = storage.puts;
    const r = await post('/ingest', view());
    expect(r.status).toBe(200);
    expect(r.body.success).toBe(true);
    expect(r.body.consent.tracking).toBe(false);
    expect(storage.map.has('affinity')).toBe(false);
    expect(storage.puts).toBe(putsBefore);          // the switch itself was the last write
    expect((await get('/snapshot')).affinity).toBeNull();
  });

  it('turned back on, the next event is kept', async () => {
    await post('/consent', { tracking: false });
    await post('/ingest', view());
    await post('/consent', { tracking: true });
    await post('/ingest', view());
    expect(storage.map.has('affinity')).toBe(true);
  });

  it('does not survive an erasure: a reset shopper starts consenting', async () => {
    await post('/consent', { tracking: false });
    await post('/reset', {});
    expect((await get('/snapshot')).consent).toEqual({ tracking: true, personalization: true });
  });
});

// src/content/consent.test.ts
// CW31 (BTIE D10), the content service's half: either switch off means the
// site's defaults whatever the holdout hash says; tracking off means the
// engine writes nothing about the request (no ring, no exposure, no ledger);
// a host that says nothing is consenting, which is what every stored session
// already says today.

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import type { Env } from '@/types/env';
import { invalidateCache, write } from '@/config/versionedStore';
import { CONTENT_KIND, LEARN_KIND, SLOTS_KIND } from './kinds';
import { armUnder, consentFromCookies, consentOf, personalizes } from './consent';
import { serveContentDecisions, invalidateLiftCache } from './service';
import { replayDecision } from '@/learn/replay';
import type { LearnConfig } from './types';
import { newAnonymousSession } from '@/identity/sessionCapability';

class FakeKV {
  store = new Map<string, string>();
  reads: string[] = [];
  async get(key: string): Promise<unknown> { this.reads.push(key); const raw = this.store.get(key); return raw === undefined ? null : JSON.parse(raw); }
  async put(key: string, value: string): Promise<void> { this.store.set(key, value); }
}
/** A namespace whose one object answers every fetch with `reply` and records what was asked. */
const fakeNs = (reply: unknown, calls: string[]) => ({
  idFromName: (n: string) => n,
  get: (id: string) => ({ fetch: async (url: string, init?: { method?: string }) => { calls.push(`${id} ${init?.method ?? 'GET'} ${new URL(url).pathname}`); return new Response(JSON.stringify(reply), { status: 200, headers: { 'Content-Type': 'application/json' } }); } }),
}) as unknown as DurableObjectNamespace;

const piece = (id: string) => ({ id, customerContentId: `cms-${id}`, type: 'editorial', title: id, tags: { line: ['Drover'] }, slotTypes: ['hero'] });

async function envWith(snapshot: Record<string, unknown>, learn: LearnConfig = { holdout: { share: 0, salt: '', arms: ['default'] } }): Promise<{ env: Env; ring: string[]; shopper: string[] }> {
  const ring: string[] = [], shopper: string[] = [];
  const env = {
    CACHE: new FakeKV(), REFLEX_HOST: 'do', ENVIRONMENT: 'test',
    SHOPPER_REFLEX: fakeNs({ ok: true, affinity: null, journeyStage: 'mid', ...snapshot }, shopper),
    DECISION_RING: fakeNs({ ok: true }, ring),
  } as unknown as Env;
  invalidateCache();
  expect((await write(env, CONTENT_KIND, 'coach', { pieces: [piece('a'), piece('b')] }, { actor: 'test' })).ok).toBe(true);
  expect((await write(env, SLOTS_KIND, 'coach', { pages: { home: [{ slot: 'hero', take: 1, weights: { line: 0.5 } }] } }, { actor: 'test' })).ok).toBe(true);
  expect((await write(env, LEARN_KIND, 'coach', learn, { actor: 'test' })).ok).toBe(true);
  return { env, ring, shopper };
}
const serve = (env: Env) => serveContentDecisions(env, { tenant: 'coach', page: 'home', visitorId: 'v1', sessionId: 's1', channel: 'direct', cf: null, cookieHeader: null, stateTenant: 'coach' });

describe('CW31 consent, the pure part', () => {
  it('reads either source, treats absence as consenting, and forces the default arm when either switch is off', () => {
    expect(consentOf(null)).toEqual({ tracking: true, personalization: true });
    expect(consentOf({ preferences: { trackingConsent: false, personalizationEnabled: true } })).toEqual({ tracking: false, personalization: true });
    expect(consentOf({ consent: { tracking: true, personalization: false } })).toEqual({ tracking: true, personalization: false });
    expect(consentOf({ consent: { tracking: 'false' } })).toEqual({ tracking: false, personalization: true });
    expect(consentFromCookies('opt_session=abc; opt_tracking_consent=false; opt_personalization_enabled=true')).toEqual({ tracking: false, personalization: true });
    expect(consentFromCookies(null)).toEqual({ tracking: true, personalization: true });
    expect(armUnder({ tracking: true, personalization: true }, 'personalized')).toBe('personalized');
    expect(armUnder({ tracking: true, personalization: false }, 'personalized')).toBe('default');
    expect(armUnder({ tracking: false, personalization: true }, 'no_learning')).toBe('default');
    expect(personalizes({ tracking: true, personalization: false })).toBe(false);
  });
});

describe('CW31 consent on the content service', () => {
  beforeEach(() => invalidateCache());

  it('W04.02 owned state honors a prior false hint without restoring legacy profile mirrors', async () => {
    const { env, ring } = await envWith({});
    Object.assign(env, { JWT_SECRET: 'w0402-synthetic-signing-material-only', JWT_ISSUER: 'i', JWT_AUDIENCE: 'a' });
    const principal = await newAnonymousSession(env, 'coach');
