    // All adapters would succeed and favour b if the live service invoked one.
    const answer = { version: 'synthetic-v1', scores: { b: 1 } };
    const fetchCall = vi.fn(async () => Response.json(answer));
    const bindingCall = vi.fn(async () => Response.json(answer));
    const aiCall = vi.fn(async () => answer);
    const bindingRead = vi.fn(() => ({ fetch: bindingCall }));
    const aiRead = vi.fn(() => ({ run: aiCall }));
    vi.stubGlobal('fetch', fetchCall);
    Object.defineProperties(env, { MODEL: { get: bindingRead }, AI: { get: aiRead } });
    const kv = env.CACHE as unknown as FakeKV;
    kv.store.set('ext:coach:coach', JSON.stringify(answer));

    const out = await serve(env);
    await out.afterResponse;
    const rec = out.records[0]!;
    expect(out.sources.learn.revision).toBe(1);
    expect(out.arm).toBe('personalized');
    expect(rec.item_id).toBe('a');
    expect(rec.explain.score_final).toBeCloseTo(0.45, 3);
    expect(out.sources.external).toEqual({ kind: external.kind, ref: external.ref, ok: false, ms: 0, version: null, reason });
    expect(rec.explain.external).toEqual({ kind: external.kind, ref: external.ref, status: 'unavailable', reason });
    expect(rec.inputs?.external).toBeUndefined();
    expect(rec.explain.drivers.some((driver) => driver.dim === 'external')).toBe(false);
    expect(kv.reads.filter((key) => key.startsWith('ext:'))).toEqual([]);
    for (const call of [fetchCall, bindingCall, aiCall, bindingRead, aiRead]) expect(call).not.toHaveBeenCalled();
    expect(shopper).toEqual(['v1 GET /snapshot']);
    expect(ring).toEqual(['coach:v1 POST /append']);

    if (external.kind === 'table') {
      const replay = await replayDecision(env, rec);
      expect(replay).toMatchObject({ ok: true, equal: true, diff: [] });
      expect(replay.replayed?.explain.external).toEqual(rec.explain.external);
      expect(kv.reads.filter((key) => key.startsWith('ext:'))).toEqual([]);
    }
  });

  it.each(['zero weight', 'default arm'])('keeps an inactive term absent: %s', async (mode) => {
    const { env } = await envWith(snapshot, {
      holdout: { share: mode === 'default arm' ? 1 : 0, salt: '', arms: ['default'] },
      external: configurations[0], slots: { hero: { external: { weight: mode === 'zero weight' ? 0 : 0.5 } } },
    });
    const fetchCall = vi.fn(async () => Response.json({ version: 'unused', scores: { b: 1 } }));
    vi.stubGlobal('fetch', fetchCall);
    const out = await serve(env);
    await out.afterResponse;
    expect(out.arm).toBe(mode === 'default arm' ? 'default' : 'personalized');
    expect(out.records[0]!.item_id).toBe('a');
    expect(out.sources.external).toBeNull();
    expect(out.records[0]!.explain.external).toBeUndefined();
    expect(out.records[0]!.inputs?.external).toBeUndefined();
    expect(fetchCall).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { createCore } from './core';
import { testHost, syntheticSession } from './testHost';

describe('core', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it('W04.02 coalesces bootstrap, scopes persisted credentials and recovers invalid grants once without bypassing503', async () => {
    const f = testHost(); f.host.storage.set('opt_visitor_id', 'victim'); f.host.cookie.set('opt_session_id', 'victim', 100);
    const core = createCore({ tenant: 'meridian' }, f.host);
    await Promise.all([core.ready(), core.send('page_view'), core.getJson('/realtime/reflex')]);
    expect(f.calls.filter(c => c.url.endsWith('/identity/session'))).toHaveLength(1);
    expect(core.visitorId).not.toBe('victim'); expect(core.headers()['X-Tenant']).toBe('meridian');
    for (const call of f.calls.filter(c => !c.url.endsWith('/identity/session'))) {
      expect(call.init?.headers?.['X-Shopper-Session']).toMatch(/^ss1\./); expect(call.url).not.toContain('ss1.');
    }
    const other = createCore({ tenant: 'coach', endpoint: 'https://other.invalid' }, f.host); await other.ready();
    expect(f.calls.at(-1)!.init?.headers).not.toHaveProperty('X-Shopper-Session');
    for (const status of [401, 503]) {
      const r = testHost(); r.host.storage.set('opt_shopper_session:https%3A%2F%2Fshop.example:coach', 'bad-persisted');
      let calls = 0;
      r.host.fetch = async (_url, init) => { calls++;
        return init?.headers?.['X-Shopper-Session'] ? { ok: false, status, json: async () => ({ ok: false }) }
          : { ok: true, status: 200, json: async () => ({ ok: true, session: syntheticSession(r.host.now()) }) };
      };
      expect(await createCore({ tenant: 'coach' }, r.host).ready()).toBe(status === 401);
      expect(calls).toBe(status === 401 ? 2 : 1);
    }
  });

  it('W04.02 delayed bootstrap/action and old socket frames cannot survive an ABA transition', async () => {
    const f = testHost(); let release!: () => void;
    const hold = new Promise<void>(r => { release = r; });
    f.host.fetch = async () => { await hold; return { ok: true, status: 200, json: async () => ({ ok: true, session: syntheticSession(f.host.now()) }) }; };
    const core = createCore({ tenant: 'coach' }, f.host), pending = core.ready();
    core.setVisitorId('newer', 'logout'); release(); expect(await pending).toBe(false); expect(core.visitorId).toBe('newer');
    const r = testHost(), active = createCore({ tenant: 'coach' }, r.host); await active.ready(); active.connect(); await Promise.resolve();
    const old = r.sockets[0]!, updates: unknown[] = []; active.on('update', u => updates.push(u));
    let done!: () => void, entered!: () => void;
    const started = new Promise<void>(resolve => { entered = resolve; }); const delayed = new Promise<void>(resolve => { done = resolve; });
    r.host.fetch = async () => { entered(); await delayed; return { ok: true, status: 200, json: async () => ({ update: { data: { segments: ['PRIVATE'] } } }) }; };
    const action = active.send('page_view'); await started;
    const visitor = active.visitorId; active.disconnect(); active.setVisitorId('other', 'logout'); active.setVisitorId(visitor, 'logout');
    old.receive({ type: 'personalization_update', data: { segments: ['PRIVATE'] } }); done();
    expect(await action).toBeNull(); expect(updates).toEqual([]);
  });

  it('builds the envelope the storefront sends, field for field', async () => {
    const { host } = testHost();
    const core = createCore({ tenant: 'coach', source: 'coach-storefront', surface: 'coach' }, host);
    await core.ready();
    const env = core.envelope('product_view', { productId: 'SKU-1' });
    expect(Object.keys(env)).toEqual(['type', 'userId', 'anonymousId', 'sessionId', 'browsingSessionId', 'data', 'source', 'surface', 'entry', 'timestamp']);
    expect(env.userId).toMatch(/^vis-/);
    expect(env.anonymousId).toBe(env.userId);
    expect(env.sessionId).toBe(core.profileSessionId);
    expect(env.browsingSessionId).toBe(core.sessionId);
    expect(env.data).toEqual({ productId: 'SKU-1' });
    expect(env.entry).toEqual({ utmMedium: 'paid_social', utmSource: 'tiktok', referrer: 'https://www.tiktok.com/', siteHost: 'shop.example' });
    expect(env.timestamp).toBe(1_725_000_000_000);
    expect(Object.keys(createCore({ tenant: 'coach' }, host).envelope('page_view'))).not.toContain('surface');
  });

  it('POSTs to /realtime/action with credentials, applies the update, and reports the receipt', async () => {
    const { host, calls } = testHost({ responses: () => ({ success: true, update: { data: { timestamp: 7, segments: ['evening_affinity'] } }, odp: { receiptId: 'r1' } }) });
    const core = createCore({ tenant: 'coach', sdkKey: 'k-1' }, host);
    const updates: unknown[] = [], receipts: unknown[] = [], sent: unknown[] = [];
    core.on('update', (u, m) => updates.push([u, m])); core.on('receipt', (r) => receipts.push(r)); core.on('sent', (_e, m) => sent.push(m));
    const out = await core.send('add_to_cart', { productId: 'SKU-1' });
    expect(calls[1]?.url).toBe('https://shop.example/realtime/action');
    expect(calls[1]?.init).toMatchObject({ method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'X-SDK-Key': 'k-1' } });
    expect(JSON.parse(calls[1]!.init!.body!)).toMatchObject({ type: 'add_to_cart', data: { productId: 'SKU-1' } });
    expect(out).toEqual({ timestamp: 7, segments: ['evening_affinity'] });
    expect(updates).toEqual([[{ timestamp: 7, segments: ['evening_affinity'] }, { fromPush: false, rttMs: 0 }]]);
    expect(receipts).toEqual([{ receiptId: 'r1' }]);
    expect(sent).toEqual([{ via: 'fetch' }]);
  });

  it('a failed POST resolves null and never throws', async () => {
    const { host } = testHost();
    host.fetch = async () => { throw new Error('offline'); };
    const core = createCore({ tenant: 'coach' }, host);
    await expect(core.send('page_view')).resolves.toBeNull();
  });

  it('uses authenticated keepalive fetch instead of a headerless beacon', async () => {
    const { host, calls, beacons } = testHost();
    const core = createCore({ tenant: 'coach' }, host);
    await core.send('purchase', { orderId: 'o1', value: 10 }, { beacon: true });
    expect(beacons).toHaveLength(0);
    expect(JSON.parse(calls[1]!.init!.body!)).toMatchObject({ type: 'purchase', data: { orderId: 'o1' } });
    expect(calls[1]!.init).toMatchObject({ keepalive: true, headers: { 'X-Shopper-Session': expect.stringMatching(/^ss1\./), 'X-Tenant': 'coach' } });
    expect(calls).toHaveLength(2);
  });

  it('opens the socket on the visitor id, heartbeats, dedupes the echo, reconnects on close', async () => {
    const { host, sockets } = testHost({ responses: () => ({ update: { data: { timestamp: 42, segments: ['a'] } } }) });
    const core = createCore({ tenant: 'coach', heartbeatMs: 1000, reconnectMs: 500 }, host);
    const status: string[] = []; core.on('socket', (s) => status.push(s));
    const updates: unknown[] = []; core.on('update', (u) => updates.push(u));
    await core.ready();
    core.connect();
    await Promise.resolve();
    expect(sockets[0]?.url).toBe(`wss://shop.example/realtime/ws?userId=${encodeURIComponent(core.visitorId)}&sessionId=${encodeURIComponent(core.profileSessionId)}&tenant=coach`);
    sockets[0]!.open();
    sockets[0]!.receive({ type: 'connected', userId: core.visitorId });
    expect(core.socketStatus).toBe('connected');
    vi.advanceTimersByTime(1000);
    expect(sockets[0]!.sent).toEqual([JSON.stringify({ type: 'heartbeat' })]);
    // The action's response applies once; the socket echo with the same timestamp is dropped.
    await core.send('product_view', { productId: 'x' });
    sockets[0]!.receive({ type: 'personalization_update', data: { timestamp: 42, segments: ['a'] } });
    expect(updates).toHaveLength(1);
    sockets[0]!.receive({ type: 'personalization_update', data: { timestamp: 43, segments: ['b'], decisionMs: 12 } });
    expect(updates).toHaveLength(2);
    // Content decisions and receipts are their own events.
    const decisions: unknown[] = []; core.on('decisions', (d) => decisions.push(d));
    sockets[0]!.receive({ type: 'content_decisions', page: 'home', decisions: [] });
    expect(decisions).toHaveLength(1);
    sockets[0]!.close();
    expect(core.socketStatus).toBe('reconnecting');
    vi.advanceTimersByTime(500);
    await Promise.resolve();
    expect(sockets).toHaveLength(2);
    core.disconnect();
    expect(core.socketStatus).toBe('closed');
    expect(status[0]).toBe('connecting');
  });

  it('reports the socket as unavailable when the host has none', () => {
    const { host } = testHost({ withSocket: false });
    const core = createCore({ tenant: 'coach' }, host);
    core.connect();
    expect(core.socketStatus).toBe('unavailable');
  });
});

// W04.01 proof-provider controls retained; W04.02 adds owned bootstrap and local generations.
import { describe, it, expect, vi } from 'vitest';
import { createCore } from './core';
import { createIdentity, type IdentifyOptions } from './identify';
import { testHost, syntheticSession } from './testHost';
import { createListen } from './listen';

const LINK = 'https://shop.example/v1/coach/identity/link';
const DETACH = 'https://shop.example/v1/coach/identity/detach';
const SHOPPER = 'sh_' + 'a'.repeat(32);
const SECOND = 'sh_' + 'b'.repeat(32);
const proof = () => ({ assertion: 'backend-proof', exp: 1_800_000_000 });
const response = (json: unknown, status = 200) => ({ ok: status >= 200 && status < 300, status, json: async () => json });
async function fixture() {
  const f = testHost();
  const core = createCore({ tenant: 'coach', sdkKey: 'site-key' }, f.host), identity = createIdentity(core);
  await core.ready();
  f.calls.length = 0;
  return { ...f, core, identity };
}
function gate() { let release!: () => void; const promise = new Promise<void>(r => { release = r; }); return { promise, release }; }

describe('identify and logout with owned sessions', () => {
  it('posts exact backend proof, adopts only a server session, persists identity and reconnects', async () => {
    const f = await fixture(), before = f.core.visitorId, oldProfile = f.core.profileSessionId;
    const person = syntheticSession(f.host.now(), SHOPPER);
    f.host.fetch = async (url, init) => { f.calls.push({ url, init }); return response({ ok: true, carry: SHOPPER, shopperId: SHOPPER, outcome: 'linked', session: person }); };
    f.core.connect(); await Promise.resolve();
    const changes: unknown[] = []; f.core.on('identity', change => changes.push(change));
    const r = await f.identity.identify('acct', { source: 'login', ...proof() });
    await Promise.resolve();
    expect(r).toEqual({ ok: true, shopperId: SHOPPER, visitorId: SHOPPER, outcome: 'linked', retried: false });
    expect(f.calls.map(c => c.url)).toEqual([LINK]);
    expect(JSON.parse(f.calls[0]!.init!.body!)).toEqual({ visitorId: before, accountId: 'acct', source: 'login', ...proof() });
    expect(f.calls[0]!.init!.headers).toMatchObject({ 'X-Tenant': 'coach', 'X-SDK-Key': 'site-key', 'X-Shopper-Session': expect.stringMatching(/^ss1\./) });
    expect(f.host.storage.get('opt_visitor_id')).toBe(SHOPPER); expect(f.host.cookie.get('opt_visitor_id')).toBe(SHOPPER);
    expect(f.core.profileSessionId).toBe(person.sessionId); expect(f.core.profileSessionId).not.toBe(oldProfile);
    expect(f.sockets.at(-1)!.url).toContain('userId=' + SHOPPER); expect(f.sockets.at(-1)!.protocols).toEqual(['shopper-session-v1', person.capability]);
    expect(changes).toEqual([{ previous: before, visitorId: SHOPPER, reason: 'identified' }]);
    expect(f.core.envelope('page_view').userId).toBe(SHOPPER);
    f.core.disconnect();
  });

  it('refused or malformed link changes no identity, while logout requires application success and rotates both identities', async () => {
    const f = await fixture(), before = f.core.visitorId;
    f.host.fetch = async () => response({ ok: false, error: 'assertion invalid' }, 401);
    expect(await f.identity.identify('acct')).toMatchObject({ ok: false, status: 401, error: 'assertion invalid' });
    expect(f.core.visitorId).toBe(before);
    expect(await f.identity.identify('')).toMatchObject({ ok: false, error: 'accountId required' });
    f.host.fetch = async () => response({ ok: true, carry: SHOPPER });
    expect(await f.identity.identify('acct', proof())).toMatchObject({ ok: false });
    expect(f.core.visitorId).toBe(before);
    const person = syntheticSession(f.host.now(), SHOPPER), fresh = syntheticSession(f.host.now());
    f.core.adoptSession(person, f.core.generation, 'identified');
    const oldBrowsing = f.core.sessionId;
    f.host.fetch = async (url, init) => { f.calls.push({ url, init }); return response({ ok: true, detached: true, session: fresh }); };
    expect(await f.identity.logout()).toMatchObject({ ok: true, visitorId: fresh.subject });
    expect(f.calls.at(-1)!.url).toBe(DETACH); expect(f.core.profileSessionId).toBe(fresh.sessionId);
    expect(f.core.sessionId).not.toBe(oldBrowsing);
  });

  it('provider409 retries once only after successful detach, with proof for the fresh owned visitor', async () => {
    const f = await fixture(), person = syntheticSession(f.host.now(), SHOPPER), fresh = syntheticSession(f.host.now()), next = syntheticSession(f.host.now(), SECOND);
    f.core.adoptSession(person, f.core.generation, 'identified');
    let links = 0;
    f.host.fetch = async (url, init) => { f.calls.push({ url, init });
      return url === DETACH ? response({ ok: true, detached: true, session: fresh })
        : ++links === 1 ? response({ ok: false, error: 'conflict' }, 409) : response({ ok: true, carry: SECOND, session: next });
    };
    const provider = vi.fn(proof);
    expect(await f.identity.identify('acct-2', { assertion: 'static-must-not-win', exp: 1, getAssertion: provider })).toMatchObject({ ok: true, shopperId: SECOND, retried: true });
    expect(f.calls.map(c => c.url)).toEqual([LINK, DETACH, LINK]);
    expect(provider.mock.calls).toHaveLength(2);
    expect(provider).toHaveBeenNthCalledWith(1, { tenant: 'coach', visitorId: SHOPPER, accountId: 'acct-2' });
    expect(provider).toHaveBeenNthCalledWith(2, { tenant: 'coach', visitorId: fresh.subject, accountId: 'acct-2' });
    expect(f.calls.filter(c => c.url === LINK).map(c => JSON.parse(c.init!.body!).assertion)).toEqual(['backend-proof', 'backend-proof']);
  });

  it('provider wins over static fields and invalid/throwing providers never fall back', async () => {
    for (const getAssertion of [() => { throw new Error('PRIVATE'); }, () => undefined, () => ({}), () => ({ assertion: ' ', exp: 1 }), () => ({ assertion: 'proof', exp: NaN }), () => ({ assertion: 'proof', exp: 1.5 }), 'invalid']) {
      const f = await fixture(), before = f.core.visitorId;
      const r = await f.identity.identify('acct', { ...proof(), getAssertion: getAssertion as unknown as IdentifyOptions['getAssertion'] });
      expect(r).toMatchObject({ ok: false, status: 0, retried: false }); expect(JSON.stringify(r)).not.toContain('PRIVATE');
      expect(f.calls).toEqual([]); expect(f.core.visitorId).toBe(before);
    }
  });

  it('static409 never detaches; failed detach/fresh proof or a second409 cannot loop', async () => {
    for (const mode of ['static', 'http', 'application', 'not-detached', 'missing', 'proof', 'second409']) {
      const f = await fixture(), before = f.core.visitorId, fresh = syntheticSession(f.host.now());
      f.host.fetch = async (url, init) => { f.calls.push({ url, init });
        if (url === LINK) return response({ ok: false, error: 'conflict' }, 409);
        if (mode === 'http') return response({ ok: true, detached: true, session: fresh }, 500);
        if (mode === 'application') return response({ ok: false, detached: true, session: fresh });
        if (mode === 'not-detached') return response({ ok: true, detached: false, session: fresh });
        if (mode === 'missing') return response(null);
        return response({ ok: true, detached: true, session: fresh });
      };
      let proofs = 0;
      const getAssertion = () => { if (++proofs > 1 && mode === 'proof') throw new Error('PRIVATE'); return proof(); };
      const r = await f.identity.identify('acct', { ...proof(), ...(mode === 'static' ? {} : { getAssertion }) });
      expect(r.ok).toBe(false); expect(r.retried).toBe(mode === 'second409'); expect(JSON.stringify(r)).not.toContain('PRIVATE');
      expect(f.calls.filter(c => c.url === LINK)).toHaveLength(mode === 'second409' ? 2 : 1);
      expect(f.calls.filter(c => c.url === DETACH)).toHaveLength(mode === 'static' ? 0 : 1);
      expect(f.core.visitorId).toBe(['proof', 'second409'].includes(mode) ? fresh.subject : before);
    }
  });

  it('rejects stale proof/link/detach and ABA, including the caller continuation microtask', async () => {
    for (const phase of ['proof', 'link', 'detach']) {
      const f = await fixture(), hold = gate(), entered = gate(), before = f.core.visitorId;
      f.host.fetch = async (url, init) => { f.calls.push({ url, init });
        if ((phase === 'link' && url === LINK) || (phase === 'detach' && url === DETACH)) { entered.release(); await hold.promise; }
        return url === LINK && phase === 'detach' ? response({ ok: false }, 409) : response({ ok: true, carry: SHOPPER, detached: true, session: syntheticSession(f.host.now(), SHOPPER) });
      };
      const pending = f.identity.identify('acct', { getAssertion: async () => { if (phase === 'proof') { entered.release(); await hold.promise; } return proof(); } });
      await entered.promise;
      f.core.setVisitorId('temporary', 'logout'); f.core.setVisitorId(before, 'logout');
      hold.release();
      expect(await pending).toMatchObject({ ok: false, status: 0, error: 'identity changed during identify', retried: false });
      expect(f.core.visitorId).toBe(before);
      expect(f.calls.filter(c => c.url === LINK)).toHaveLength(phase === 'proof' ? 0 : 1);
    }
    for (const status of [200, 409]) {
      const f = await fixture();
      f.host.fetch = async (url, init) => { f.calls.push({ url, init }); return response({ ok: status === 200, carry: SHOPPER, session: syntheticSession(f.host.now(), SHOPPER) }, status); };
      const post = f.core.postJson;
      f.core.postJson = async (path, body) => { const result = await post(path, body); queueMicrotask(() => queueMicrotask(() => f.core.setVisitorId('newer', 'logout'))); return result; };
      expect(await f.identity.identify('acct', { getAssertion: proof })).toMatchObject({ ok: false, error: 'identity changed during identify' });
      expect(f.calls.map(c => c.url)).toEqual([LINK]);
    }
  });

  it('W04.02 transition pauses new data, clears cached decisions and ignores stale callbacks/results', async () => {
    const f = await fixture(), listen = createListen(f.core), hold = gate(), entered = gate();
    listen.apply({ page: 'home', decisions: [] });
    const pending = f.identity.identify('acct', { getAssertion: async () => { entered.release(); await hold.promise; return proof(); } });
    await entered.promise; expect(listen.current()).toBeNull();
    expect(await f.core.send('page_view')).toBeNull(); expect(await listen.hydrate({ page: 'home' })).toBeNull(); expect(f.calls).toEqual([]);
    f.core.setVisitorId('newer', 'logout'); hold.release(); expect((await pending).ok).toBe(false);
    const c = await fixture(), updates: unknown[] = [];
    c.host.fetch = async () => response({ update: { data: { segments: ['private'] } }, odp: { receiptId: 'private' } });
    c.core.on('sent', () => c.core.setVisitorId('callback-newer', 'logout')); c.core.on('update', update => updates.push(update));
    expect(await c.core.send('page_view')).toBeNull(); expect(updates).toEqual([]);
  });

  it('W04.02 failed logout discards the local grant without clearing a newer transition', async () => {
    for (const mode of ['http', 'application', 'missing']) {
      const f = await fixture(); f.core.adoptSession(syntheticSession(f.host.now(), SHOPPER), f.core.generation, 'identified');
      f.host.fetch = async () => response(mode === 'missing' ? null : { ok: mode !== 'application', detached: true }, mode === 'http' ? 500 : 200);
      expect((await f.identity.logout()).ok).toBe(false); expect(f.core.visitorId).toBe(''); expect(f.core.headers()).not.toHaveProperty('X-Shopper-Session');
    }
    const f = await fixture(), hold = gate(), entered = gate();
    f.host.fetch = async () => { entered.release(); await hold.promise; return response(null, 500); };
    const pending = f.identity.logout(); await entered.promise;
    const generation = f.core.beginTransition(), newer = syntheticSession(f.host.now(), SECOND);
    expect(f.core.adoptSession(newer, generation, 'identified')).toBe(true); f.core.finishTransition(generation); hold.release();
    expect((await pending).ok).toBe(false); expect(f.core.visitorId).toBe(SECOND);
  });
});

/* edge-personalization SDK v0.1.0 — one package: core (identity, transport), emit (four capture paths), listen (decisions). */
"use strict";
(() => {
  // src/sdk/identity.ts
  var DEFAULT_VISITOR_KEY = "opt_visitor_id";
  var YEAR_SECONDS = 60 * 60 * 24 * 365;
  function writeVisitorId(host, key, id) {
    try {
      host.storage.set(key, id);
    } catch {
    }
    try {
      host.cookie.set(key, id, YEAR_SECONDS);
    } catch {
    }
  }
  var DEFAULT_SESSION_KEY = "opt_session";
  var DEFAULT_SESSION_IDLE_MS = 30 * 60 * 1e3;
  function currentSessionId(host, key = DEFAULT_SESSION_KEY, idleMs = DEFAULT_SESSION_IDLE_MS) {
    const now = host.now();
    let stored = null;
